import{_ as n,a as t,b as i,c as r,d as s,e as a,f as d,g as l,h as o,i as g,j as u,k as h,l as c,m as b,n as m,o as p,p as k,q as f,r as S,s as w,t as z,u as v,v as E,w as x,x as T,y as A,z as B,A as H,B as W,C as D,D as L,E as F,F as R,G as Z,H as V,I}from"./chunks/dashboard-widget.9Kkq69BW.js";import{_ as M,o as _,c as P,a3 as C}from"./chunks/framework.BlfGB29P.js";const Q=JSON.parse('{"title":"Widget-Übersicht","description":"","frontmatter":{"title":"Widget-Übersicht"},"headers":[],"relativePath":"projects/grafik-visual-studio/widgets.md","filePath":"projects/grafik-visual-studio/widgets.md","lastUpdated":1793126673000}'),q={name:"projects/grafik-visual-studio/widgets.md"};function N(G,e,U,y,K,O){return _(),P("div",null,[...e[0]||(e[0]=[C('<h1 id="widget-ubersicht" tabindex="-1">Widget-Übersicht <a class="header-anchor" href="#widget-ubersicht" aria-label="Permalink to &quot;Widget-Übersicht&quot;">​</a></h1><p><strong>CSS-Standard ab Studio 0.1.271:</strong> Alle Widgets außer Industrial erhalten die vollständigen Gruppen <strong>CSS Allgemein</strong>, <strong>CSS Font &amp; Text</strong>, <strong>CSS Hintergrund</strong>, <strong>CSS Ränder</strong> und <strong>CSS Schatten und Abstand</strong>. Das gilt auch für künftig installierte Widgetsets. Vorhandene Einstellungen bleiben erhalten; neu ergänzte optionale Gruppen sind zunächst deaktiviert. Industrial verwendet weiterhin seine eigenen Gehäuse-Einstellungen.</p><p>Eigenständiges externes Set: <a href="./calendar-plus">Calendar +</a>, ab <strong>Studio 0.1.266</strong>. Erkennt alle Home-Assistant-Kalender automatisch, zunächst alle aktiviert; je Kalender ein-/ausblendbar mit eigener Farbe und Hintergrundfarbe. Terminliste, Tagesgruppen und Detail-Popup, automatische DE/EN-Sprache. Inspiriert von <a href="https://github.com/xBourner/calendar-card-plus" target="_blank" rel="noreferrer">xBourner/calendar-card-plus</a>.</p><p><strong>Autosave ab Studio 0.1.265:</strong> Die eingestellte Verzögerung (z. B. zwei Sekunden) beginnt nach der zuletzt erkannten Änderung. Nach einem Speicherfehler folgt bei aktiviertem Autosave nach fünf Sekunden ein neuer Versuch, auch ohne weitere Bearbeitung. Eine hängende Speicheranfrage wird nach 15 Sekunden mit einer Zeitüberschreitung beendet und blockiert weitere Speicherungen nicht dauerhaft. Änderungen während einer Anfrage bleiben für die nächste Speicherung erhalten. Manuelles Speichern wartet bei Bedarf auf die laufende Anfrage.</p><p>Ab <strong>Studio 0.1.264</strong> speichern <strong>Runtime</strong> und <strong>Neuer Tab</strong> das aktuelle Projekt vor dem Öffnen. Dadurch übernimmt die Runtime auch gerade verschobene Widgets ohne vorherigen manuellen Speicherklick. Dies gilt für alle Widgetsets. Laufende Speichervorgänge werden abgewartet; bei einem Speicherfehler bleibt der Editor geöffnet. Bereits geöffnete Runtime-Tabs müssen nach späteren Änderungen neu geladen werden.</p><p>Eigenständiges externes Set: <a href="./printer">Printer</a> mit Druckerstatus und <strong>1–6 automatisch gleichmäßig verteilten Patronen</strong>, ab Studio <strong>0.1.261</strong>. Inspiriert von <a href="https://github.com/ADNPolymerase/ha-printer-card" target="_blank" rel="noreferrer">ADNPolymerase/ha-printer-card</a>, eigene SVG-Zeichnung und lesende Home-Assistant-Anbindung.</p><p>Weiteres externes Set: <a href="./technic">Technic</a> mit <strong>Window – Wall</strong>, ab Studio 0.1.197. Inspiriert von den ioBroker-Technic-Widgets von Sefina-DS, mit eigener HA-Anbindung und MIT-Lizenz im Paket.</p><p>Zusätzlich nachinstallierbar: <a href="./weather-heating">Wetter und Heizung</a> mit <strong>Allgemeines Diagramm</strong> (ab 0.1.187), <strong>Balkendiagramm für zwei Wochen</strong> (ab 0.1.188), <strong>Wetter-Widget</strong> (ab 0.1.189), <strong>Übersicht über Heizräume</strong> (ab 0.1.190), <strong>METEORED-Wetter-Widget</strong> (ab 0.1.191), <strong>Fensterstatus-Übersicht</strong> (ab 0.1.192), <strong>Meinen Vermieter informieren</strong> (ab 0.1.193) und <strong>Allgemeine Heizparameter</strong> (ab 0.1.194). Das optionale Paket zählt nicht zu den 74 integrierten Widgets und erhält automatisch eine freie Set-Farbe.</p><p>Der aktuelle Widget-Katalog enthält <strong>74 Einträge in fünf Gruppen</strong>. Die Namen entsprechen der Palette im Editor. Widgets mit Entitätsbindung lesen in der Runtime den aktuellen Home-Assistant-Zustand; ohne Entität verwenden sie Vorschauwerte oder ausdrücklich konfigurierte Dockpunktwerte. Schreibzugriff ist auf die unten genannten Widgets und Entitätstypen begrenzt. Externe Zustandsänderungen werden derzeit alle fünf Sekunden abgefragt. Eigene Änderungen an einem Regler wirken sofort auf Number und SVG-Line, während der Schreibauftrag an Home Assistant läuft.</p><p>Die VIS2-inspirierten Basis-Widgets behalten ihre englischen Namen. Interaktive Widgets wie Terminkalender und Schieberegler verwenden übersetzte Palettennamen. Frühere Palettennamen können weiterhin als Suchbegriffe dienen. Bereits gespeicherte eigene Widget-Namen bleiben unverändert.</p><p><strong>HTML Logout wird nicht übernommen</strong> und ist nicht als zukünftiges Studio-Widget vorgesehen.</p><p>Ab Studio 0.1.135 bleibt der technische Widget-Name in der Editoroberfläche. Auf der Arbeitsfläche und in der Runtime erscheinen nur eigene Beschriftungen; neue Widgets starten ohne voreingestellten Titel. Das gilt zentral auch für zukünftige Widget-Pakete und die LineBox. Beim Laden älterer Projekte werden bisherige Standardtitel einmal entfernt. Individuelle Beschriftungen bleiben erhalten; anschließend kannst du auch einen früheren Standardtext ausdrücklich wieder eintragen.</p><p><strong>Schreibfähige Widgets:</strong> Switch, Icon Toggle Button, Bool Checkbox, Bool Select, Bool SVG und Bool HTML (control) schalten gebundene <code>switch</code>-, <code>light</code>- oder <code>input_boolean</code>-Entitäten. Bulb on/off schaltet diese Entitäten oder setzt einen <code>input_number</code>-Helfer auf sein konfiguriertes Minimum/Maximum. Slider, Schieberegler und Radialer Schieberegler schreiben nur <code>input_number</code>; Input val schreibt <code>input_number</code> oder <code>input_text</code>. Note schreibt im Notizdialog an einen <code>input_text</code>-Helfer ohne Attributauswahl. Universal Element schreibt im Schaltermodus seine false-/true-Werte und im Tastermodus den nächsten konfigurierten Wert an eine passende schaltbare Entität oder einen Zahlen-/Texthelfer. Bei einer unpassenden oder nicht verfügbaren Entität ist die Bedienung gesperrt. Checkbox und Schalten schreiben ihre konfigurierten Wertepaare an passende Schalter oder Zahlen-/Texthelfer. Dropdown wählt Optionen in <code>select</code>/<code>input_select</code> oder eigene Werte in Zahlen-/Texthelfern. Die übrigen Widgets schreiben keinen HA-Zustand.</p><h2 id="ha-grafik-–-basis-46" tabindex="-1">HA Grafik – Basis (46) <a class="header-anchor" href="#ha-grafik-–-basis-46" aria-label="Permalink to &quot;HA Grafik – Basis (46)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Aktuelle Funktion</th></tr></thead><tbody><tr><td>Tabs</td><td>Ab Studio 0.1.116: 1–20 horizontale oder vertikale Reiter; horizontal Standard, zentriert oder Gesamtbreite. Pro Tab Titel, Symbol oder Bild, Symbolgröße/-farbe und Überlauf X/Y. Der Inhalt ist eine eigene Widget-Fläche oder eine vorhandene Projektseite. Nur der aktive Inhalt wird in der Runtime eingebettet; die Auswahl bleibt lokal im Browser gespeichert.</td></tr></tbody></table><h3 id="tabs-bearbeiten" tabindex="-1">Tabs bearbeiten <a class="header-anchor" href="#tabs-bearbeiten" aria-label="Permalink to &quot;Tabs bearbeiten&quot;">​</a></h3><p>Ab Studio 0.1.122 bietet die Haupteinstellung <strong>Tabs</strong> den Regler <strong>Inaktive Reiter abdunkeln (%)</strong> von 0 bis 90. Bei 0 bleiben die Farben unverändert, bei 90 bleiben 10 % Helligkeit. Hintergrund, Text und Symbol der inaktiven Reiter werden gemeinsam abgedunkelt; der aktive Reiter und der Tab-Inhalt bleiben unverändert. Die Einstellung gilt horizontal und vertikal und wird im Projekt gespeichert.</p><p>Ab Studio 0.1.121 stellst du in der Haupteinstellung <strong>Tabs</strong> die <strong>Textfarbe aktiv</strong> und <strong>Textfarbe nicht aktiv</strong> getrennt ein. Sie gelten für die Beschriftung aller Reiter, abhängig von der aktuellen Auswahl. Bleibt ein Wert leer, wird die bisherige <strong>Tab-Farbe</strong> verwendet. Die Symbolfarbe je Tab bleibt unabhängig; die Tab-Farbe bestimmt weiterhin die aktive Markierung.</p><p><strong>Überlauf X</strong> und <strong>Überlauf Y</strong> bieten ab Studio 0.1.120 die Auswahl <code>none</code>, <code>visible</code>, <code>hidden</code>, <code>scroll</code>, <code>auto</code>, <code>initial</code> und <code>inherit</code>. <code>none</code> entfernt die eigene CSS-Vorgabe, <code>visible</code> lässt überstehenden Inhalt sichtbar, <code>hidden</code> schneidet ihn ab, <code>scroll</code> aktiviert Scrollleisten und <code>auto</code> zeigt sie bei Bedarf. <code>initial</code> verwendet den CSS-Ausgangswert, <code>inherit</code> übernimmt die Vorgabe des übergeordneten Elements. Ohne gespeicherte Auswahl bleibt <code>auto</code> der Standard. CSS kann die beiden Achsen gemeinsam beeinflussen, insbesondere wenn <code>visible</code> mit einer scrollbaren anderen Achse kombiniert wird.</p><p>Ab Studio 0.1.119 kannst du unter jedem <strong>Tab [n]</strong> die <strong>Tab-Hintergrundfarbe</strong> unabhängig einstellen. Sie färbt den jeweiligen Reiter in horizontalen und vertikalen Layouts; die Markierung des aktiven Tabs bleibt sichtbar.</p><p>Füge <strong>Tabs</strong> aus der Palette ein und stelle Breite und Höhe einmal am Hauptwidget ein. In <strong>Tab [1]</strong>, <strong>Tab [2]</strong> usw. wählst du die Inhaltsart. <strong>Tabfläche bearbeiten</strong> öffnet die eigene Fläche mit der normalen Widget-Palette oder die referenzierte Projektseite. <strong>Zurück zum Tabs-Widget</strong> führt zum Hauptwidget zurück. Die eigene Inhaltsgröße ergibt sich aus dem Hauptwidget abzüglich 44 px für horizontale Reiter beziehungsweise bis zu 120 px für vertikale Reiter (höchstens die halbe Widget-Breite). Eigene Flächen gehören zum Widget und erscheinen nicht als separate Projektseiten. Vorhandene Seiten bleiben gemeinsam genutzte Referenzen; Änderungen wirken auf alle Einbettungen.</p><p>Ab Studio 0.1.124 werden aktive Tab-Inhalte direkt aus dem geöffneten Projekt dargestellt, ohne einen iFrame oder erneutes Laden beim Tabwechsel. Ein Klick auf die Inhaltsfläche öffnet ihre Bearbeitung; nach der Rückkehr sind auch ungespeicherte Änderungen sofort sichtbar. Speichere weiterhin vor dem Öffnen einer separaten Runtime, insbesondere bei deaktiviertem Auto-Save. Die Runtime fragt Entitätswerte auch für die aktiven Tab-Inhalte ab. Größere vorhandene Seiten werden ohne automatische Skalierung angezeigt; Überlauf X/Y steuert die Scrollbarkeit. Bei verringerter Tabanzahl bleiben die ausgeblendeten eigenen Inhalte gespeichert und erscheinen bei erneuter Erhöhung wieder. Kopieren, Gruppieren sowie Export/Import erhalten eigene Inhalte; Kopien bekommen neue Widget- und Gruppen-IDs. Zyklische Seiteneinbettungen werden verhindert. Weitere Tabs-Widgets innerhalb eigener Tabflächen sind zunächst nicht unterstützt. Die Umsetzung ist eigenständig; ein VIS2-Import ist damit nicht verbunden.</p><h3 id="weitere-basis-widgets" tabindex="-1">Weitere Basis-Widgets <a class="header-anchor" href="#weitere-basis-widgets" aria-label="Permalink to &quot;Weitere Basis-Widgets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Widget</th><th>Aktuelle Funktion</th></tr></thead><tbody><tr><td>link</td><td>Formatierbarer HTML-Inhalt als Link zu einer URL.</td></tr><tr><td>Note</td><td>Notizzettel mit Entitätswert, Testtext, optional ausgeblendeter Ecke und Textdialog.</td></tr><tr><td>Screen Resolution</td><td>Zeigt die aktuelle Fensterauflösung an.</td></tr><tr><td>Red Number</td><td>Zahlenwert als farbiger Kreis oder Pin mit anpassbarem Radius.</td></tr><tr><td>Bool SVG</td><td>Wählt nach dem aktuellen Zustand eines von zwei SVG-Motiven; kann eine schaltbare Entität oder einen passenden 0/1-Helfer steuern.</td></tr><tr><td>SVG shape</td><td>Zeichnet eine geometrische SVG-Form mit Farbe, Strichbreite, Rotation und Skalierung.</td></tr><tr><td>Input val</td><td>Text- oder Zahlen-Eingabefeld (150 × 70). Zahlenmodus mit optionalem min/max; Nur-lesend erlaubt auch Sensoren. Enter bestätigt immer. Auto-setzen schreibt nach der einstellbaren Eingabepause (Standard 1000 ms), auch mit withEnter. withEnter ergänzt eine Bestätigungstaste für ungesendete Eingaben. Ohne Auto-setzen schreibt das Verlassen des Feldes nichts. Schreibziele sind passende <code>input_number</code>-/<code>input_text</code>-Helfer; ohne Entität bleibt die Eingabe lokal.</td></tr><tr><td>View in widget</td><td>Bettet eine Studio-Projektseite ein (Standard 300 × 200); rekursive Einbettung wird verhindert. Für HA-Dashboards gibt es ein eigenes Widget unter Spezial.</td></tr><tr><td>View in widget 8</td><td>Wählt eine von bis zu 50 Seiten anhand des Indexzustands.</td></tr><tr><td>iFrame</td><td>Bettet eine URL ein, sofern die Zielseite dies erlaubt; mit Rahmen-, Scroll- und Aktualisierungsoptionen.</td></tr><tr><td>iFrame 8</td><td>Wählt anhand des Indexzustands einen Frame aus [0] bis [20], mit eigener Sandbox-Einstellung je URL.</td></tr><tr><td>Image 8</td><td>Wählt anhand des Indexzustands Bild [0] bis maximal Bild [200].</td></tr><tr><td>AckFlag HTML</td><td>Zeigt zwei konfigurierbare HTML-Zustände; Home Assistant hat kein natives ioBroker-<code>ack</code>-Flag.</td></tr><tr><td>Icon Toggle Button</td><td>Schaltfläche mit getrennten Bildern für Ein und Aus; kann eine schaltbare Entität steuern.</td></tr><tr><td>Switch</td><td>Grafischer Ein/Aus-Schalter; kann eine schaltbare Entität steuern.</td></tr><tr><td>Bool Checkbox</td><td>Ein/Aus-Auswahl; kann eine schaltbare Entität steuern.</td></tr><tr><td>Bulb on/off</td><td>Lampensymbol mit getrennten Ein-/Aus-Bildern; steuert eine schaltbare Entität oder einen Zahlenhelfer.</td></tr><tr><td>Slider</td><td>Regler mit Minimum, Maximum und Schrittweite; Min-/Max-Beschriftungen sind per Checkbox zuschaltbar. Die Grenzen sollten zum Helfer passen, etwa <code>-200</code> bis <code>200</code>. Ein gewählter <code>input_number</code>-Helfer liefert den aktuellen Wert; beim Ziehen aktualisiert der Regler abhängige Number- und SVG-Line-Widgets sofort und schreibt beim Loslassen nach Home Assistant. Ohne Entität bleibt die Änderung lokal. Ab Studio 0.1.114 sind Schienenfarbe, aktive Farbe, Schienenstärke und Rundung sowie Reglerfarbe, Größe und Rundung getrennt einstellbar. Der Spurtyp bietet Normal (Minimum bis Wert), Umgekehrt (Wert bis Maximum) oder keine aktive Spur. Schiene und Regler haben eigene Schatten mit X/Y-Versatz, Unschärfe, Ausdehnung und CSS-/RGBA-Farbe. Rundung: 0 % eckig, 100 % vollständig gerundet; Schatten mit allen Größenwerten 0 sind aus. Skalenmarkierungen bleiben oben/unten mit optionalen Zahlen verfügbar.</td></tr><tr><td>Number</td><td>Zeigt den formatierten Zahlenwert mit Multiplikator und Nachkommastellen, bei fehlendem Entitätswert <code>--</code>. Ab Studio 0.1.125 werden <strong>HTML voranstellen</strong> und <strong>HTML anhängen (Singular/Plural)</strong> auch bei gebundener HA-Entität im Editor und in der Runtime angezeigt und bei Sofortaktualisierungen erhalten. Singular gilt für den mit dem Multiplikator berechneten Wert 1, sonst Plural; ohne HTML-Nachtext dient die konfigurierte Einheit als Ersatz. Der Vorschautitel wird ohne Entität angezeigt. Getrennt vom grafischen Widget „Red Number“.</td></tr><tr><td>String</td><td>Textwert mit optionalem Icon und HTML vor oder nach dem Wert.</td></tr><tr><td>String (unescaped)</td><td>Stellt einen HTML-Wert mit Vor- und Nachsatz dar.</td></tr><tr><td>String img src</td><td>Zeigt ein Bild aus einer URL im Zustand.</td></tr><tr><td>TimesValue</td><td>Formatiert einen Zeitwert aus dem Zustand.</td></tr><tr><td>Timestamp Value</td><td>Formatiert einen Zeitstempel aus dem Zustand.</td></tr><tr><td>Timestamp</td><td>Formatiert den Zeitpunkt der letzten HA-Aktualisierung.</td></tr><tr><td>Last change Timestamp</td><td>Formatiert den Zeitpunkt der letzten HA-Zustandsänderung.</td></tr><tr><td>ValueList Text</td><td>Zeigt einen über den Indexzustand ausgewählten Listeneintrag als Text.</td></tr><tr><td>ValueList HTML</td><td>Zeigt einen über den Indexzustand ausgewählten Listeneintrag als HTML.</td></tr><tr><td>ValueList HTML Style</td><td>Zeigt einen HTML-Listeneintrag mit zugeordnetem CSS-Stil.</td></tr><tr><td>Bool HTML</td><td>Zeigt je nach Zustand einen von zwei HTML-Inhalten, mit optionalem HTML davor und dahinter.</td></tr><tr><td>Bool Select</td><td>Ein/Aus-Auswahl mit anpassbaren Beschriftungen; kann eine schaltbare Entität steuern.</td></tr><tr><td>Bool HTML (control)</td><td>Anklickbare Ein/Aus-HTML-Anzeige; kann eine schaltbare Entität steuern.</td></tr><tr><td>HTML State</td><td>HTML-Schaltfläche, die bei jedem Klick einen festen Wert schreibt und optional eine URL aufruft.</td></tr><tr><td>Table</td><td>Tabelle aus JSON-Daten mit Zeilenauswahl und Druckoption; ein gebundener HA-Zustand muss JSON-Zeilen enthalten.</td></tr><tr><td>Full Screen</td><td>Schaltfläche für den Vollbildmodus der Oberfläche.</td></tr><tr><td>Bar</td><td>Horizontaler oder vertikaler Balken für einen Zahlenwert.</td></tr><tr><td>HTML</td><td>Frei konfigurierbarer HTML-Inhalt.</td></tr><tr><td>HTML navigation</td><td>Schaltfläche oder Link zu einer Projektseite, URL oder einem HA-Pfad.</td></tr><tr><td>filter - dropdown</td><td>Filtert Runtime-Widgets anhand des in „Generell“ gesetzten Filterworts.</td></tr><tr><td>Text</td><td>Freies Textfeld ohne Entitätsbindung.</td></tr><tr><td>Border</td><td>Rahmen mit Titel, Titelposition, Kopfbereich und Farben.</td></tr><tr><td>Horizontal line</td><td>Horizontale Trennlinie mit einstellbaren Enden und Einrasten.</td></tr><tr><td>Vertical line</td><td>Vertikale Trennlinie mit einstellbaren Enden und Einrasten.</td></tr><tr><td>Gauge</td><td>Einfache Messwertanzeige mit Einheit.</td></tr><tr><td>Image</td><td>Bildquelle, Strecken und gesteuertes Neuladen; optionale native Browserinteraktionen. Standardgröße 200 × 130 px.</td></tr></tbody></table><p>Die folgenden Bilder stammen aus deutschen Testprojekten. Frühere CSS-Häkchen sind in den Bildunterschriften gekennzeichnet; maßgeblich ist das im Text beschriebene aktuelle Verhalten.</p><h3 id="css-vorgaben" tabindex="-1">CSS-Vorgaben <a class="header-anchor" href="#css-vorgaben" aria-label="Permalink to &quot;CSS-Vorgaben&quot;">​</a></h3><p><img src="'+n+'" alt="Verpflichtendes CSS Allgemein und optionale CSS-Bereiche"></p><p><em>CSS Allgemein ist angehakt und gesperrt; die übrigen CSS-Gruppen sind optional.</em></p><p>Ab <strong>0.1.154</strong> bleibt <strong>CSS Allgemein</strong> bei allen Widgets verpflichtend aktiv, einschließlich bereits gespeicherter Projekte und zukünftiger Widget-Pakete. Position und Größe bleiben damit im Export erhalten. Frühere Hinweise auf deaktivierte CSS-Bereiche gelten ab dieser Version nur für die übrigen CSS-Gruppen.</p><h3 id="input-val-eingegebener-wert" tabindex="-1">Input val / Eingegebener Wert <a class="header-anchor" href="#input-val-eingegebener-wert" aria-label="Permalink to &quot;Input val / Eingegebener Wert&quot;">​</a></h3><p>Ab <strong>0.1.157</strong> bietet der Zahlenmodus optionale <strong>min/max</strong>. <strong>Auto-setzen</strong> übernimmt nach der eingestellten Pause, standardmäßig <strong>1000 ms</strong>, auch bei aktiviertem <strong>withEnter</strong>. Enter bestätigt immer. <strong>withEnter</strong> ergänzt eine Bestätigungstaste für ungesendete Änderungen; ohne Auto-setzen schreibt das Verlassen des Feldes nichts. Manuelle Eingaben bleiben bis zur Bestätigung erhalten. Nur-lesend kann auch Sensorwerte anzeigen; zum Schreiben von Zahlen/Text sind passende <code>input_number</code>-/<code>input_text</code>-Helfer nötig. Im Editor wird nie nach HA geschrieben.</p><p><img src="'+t+'" alt="Detail der Eingabeeinstellungen mit Zahlengrenzen und Auto-setzen"></p><p><em>Ausschnitt der Eingabeeinstellungen: min/max 0–1000, Verzögerung 1000 ms und Nur-lesend aktiviert.</em></p><p>Mit Style sind „HTML voranstellen“ die Feldbeschriftung und „HTML anhängen“ der Hilfstext unter dem Feld. <strong>Kein Style</strong> zeigt stattdessen bereinigtes HTML vor und hinter einem einfachen Eingabefeld. Die Varianten sind standard, outlined und filled. Leere, ungültige oder außerhalb von min/max liegende Zahlen werden nicht geschrieben. Neue Widgets aktivieren nur CSS Allgemein; die Umsteigerhinweise lassen sich zentral abschalten.</p><h3 id="string-zeichenfolge" tabindex="-1">String / Zeichenfolge <a class="header-anchor" href="#string-zeichenfolge" aria-label="Permalink to &quot;String / Zeichenfolge&quot;">​</a></h3><p><img src="'+i+'" alt="String-Vorschau mit 43-Pixel-Lampensymbol und formatierten Vor- und Nachtexten"></p><p><em>Editorbeispiel mit 43-px-Symbol, fettem Vorsatz und kursivem Nachsatz; der Quellwert bleibt normaler Text.</em></p><p><a href="/images/grafik-visual-studio/string.png">Bild in voller Größe öffnen</a></p><p>Ab <strong>0.1.156</strong> haben <strong>HTML voranstellen</strong>, <strong>HTML anhängen</strong> und <strong>Testtext</strong> den HTML-Editor. Der Entitätswert und Testtext werden trotzdem als normaler Text dargestellt: <code>&lt;b&gt;Test&lt;/b&gt;</code> im Testtext zeigt die Tags wörtlich. Nur Vor- und Nachsatz werden als bereinigtes HTML formatiert. Ein nicht leerer Testtext übersteuert die Quelle im Editor; in der Runtime gilt die Quelle. Ohne Entität bleibt der Runtime-Wert leer, fehlende Entität oder fehlendes Attribut ergibt <code>--</code>.</p><p>Für den ioBroker-Datenpunkt <code>…attribute.friendly_name</code> wählst du die zugehörige <strong>Home-Assistant-Entität</strong> und trägst unter <strong>HA-Attribut (leer: Zustand)</strong> <code>friendly_name</code> ein. Ein leeres Attributfeld zeigt den Zustand. Dafür ist kein Helfer nötig; die Auswahl liest nur. Der optionale Ausgangspunkt gibt denselben Quellwert weiter, ohne Vor-/Nachsatz oder Editor-Testtext.</p><p><strong>Icon</strong> verwendet die vorhandene Icon-/Bildauswahl. <strong>Symbolgröße in Pixel</strong> erscheint nur bei gewähltem Icon, bietet 5–200 px und startet bei 24 px. Der Exportwert <code>43</code> ergibt ein 43 × 43 px großes Symbol. Neue Widgets starten mit leeren Inhalten, 100 × 30 px und ausschließlich aktiviertem CSS Allgemein; für größere Symbole die Widget-Höhe entsprechend anpassen. Die Umsteigerhinweise zu Attributen und Testtext sind zentral abschaltbar.</p><h3 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h3><p><img src="'+r+'" alt="HTML-Editor mit Aktualisierungsintervall"></p><p><em>Frühere HTML-Testansicht mit 500-ms-Intervall. Seit 0.1.154 bleibt CSS Allgemein verpflichtend aktiv.</em></p><p><strong>HTML</strong> zeigt eigenen HTML-Inhalt mit dem vorhandenen HTML-Editor. <code>&lt;b&gt;Hallo&lt;/b&gt;&lt;i&gt; Susi&lt;/i&gt;</code> ergibt <strong>Hallo</strong> und ein kursives <em>Susi</em>. <strong>Updatezeit (ms)</strong> baut diesen Inhalt im eingestellten Abstand neu auf; <code>0</code>, leer oder <code>null</code> deaktiviert die periodische Aktualisierung. Der Bereich reicht bis 180000 ms in Schritten von 100 ms. Dies ist keine HA-Abfragezeit und benötigt keinen Helfer.</p><p>Studio bereinigt das HTML: Eingebettete Skripte und Event-Handler werden nicht ausgeführt. Das unterscheidet sich vom VIS2-Original und wird als abschaltbarer Umsteigerhinweis erklärt. <code>{value}</code> ist kein Platzhalter. Neue Widgets beginnen mit leerem HTML, 200 × 130 px und ausschließlich aktiviertem CSS Allgemein; vorhandene Inhalte bleiben erhalten. Der optionale Ausgangspunkt ist weiterhin verfügbar.</p><h3 id="html-navigation" tabindex="-1">HTML navigation <a class="header-anchor" href="#html-navigation" aria-label="Permalink to &quot;HTML navigation&quot;">​</a></h3><p><strong>HTML</strong> ist die frei formatierbare Beschriftung; <strong>View zum Navigieren</strong> wählt eine Projektseite. Ein Klick oder Enter/Leertaste wechselt nur in der Runtime dorthin, ohne HA-Schreibziel oder Helfer. Ohne Ziel bleibt die Beschriftung sichtbar. Neue Widgets starten mit leerem HTML, 200 × 130 px und nur <strong>CSS Allgemein</strong> aktiviert. Gespeicherte URL-/HA-Pfad-Ziele und alte Beschriftungen bleiben nutzbar.</p><p><strong>Unteransicht</strong> aus VIS2 ist für spezielle Navigationssysteme wie Jaeger Design vorgesehen und in Studio noch nicht angebunden; das Feld ist deaktiviert. Es bezeichnet keinen Studio-Tab. Die abschaltbaren Umsteigerhinweise erklären diese Einschränkung und die HTML-Bereinigung.</p><h3 id="filter-dropdown" tabindex="-1">filter - dropdown <a class="header-anchor" href="#filter-dropdown" aria-label="Permalink to &quot;filter - dropdown&quot;">​</a></h3><p><img src="'+s+'" alt="Filtereditor mit HEX-Farben und Standardauswahl"></p><p><em>Zwei Einträge: Der erste hat ein Icon und HEX-Farben, der zweite ist die Standardauswahl.</em></p><p><a href="/images/grafik-visual-studio/filter-editor.png">Bild in voller Größe öffnen</a></p><p>Ab <strong>0.1.155</strong> bearbeitet <strong>editor → Bearbeiten</strong> die Einträge mit Wert, Titel, Symbol, Bild, Textfarbe, aktiver Farbe und Standardauswahl. Einträge lassen sich hinzufügen, löschen und mit den Pfeiltasten im Dialog umsortieren. Bei Einfachauswahl kann nur ein Eintrag Standard sein; Mehrfachauswahl erlaubt mehrere. <strong>Anwenden</strong> übernimmt die Änderungen, <strong>Abbrechen</strong> verwirft sie.</p><p>Farben werden als <strong>HEX</strong> gespeichert: <code>rgba(120,112,160,1)</code> entspricht <code>#7870A0</code>, <code>rgba(65,77,25,1)</code> entspricht <code>#414D19</code>. Optional ist ein Alphakanal als <code>#RRGGBBAA</code> möglich. Das Farbfeld kann auch geleert werden. <strong>Aktive Farbe</strong> ist bei den Tasten die Textfarbe des ausgewählten Eintrags; der Hintergrund folgt der Variante. Symbol hat Vorrang vor Bild.</p><p><strong>Typ</strong> bietet Dropdown-Menü, horizontale oder vertikale Tasten. Tasten haben outlined/contained/text; Dropdowns standard/outlined/filled sowie optional Name, Autofokus und Klein. Die Dropdown-Liste zeigt Icons/Bilder und unterstützt Tastaturbedienung. <strong>Keine Option Kein Filter</strong> blendet die Rücksetzoption aus; ihr Text ist ansonsten frei wählbar.</p><p>Filterwerte passen zu <strong>Filterwort</strong> der Widgets auf derselben Seite. Komma oder Semikolon im Wert kann mehrere Filterwörter ansprechen. Widgets ohne Filterwort bleiben sichtbar. Standardauswahl und Filterung gelten in der Runtime; im Editor bleiben die Widgets bearbeitbar. Jede Seite hat eine eigene Auswahl. Es wird kein HA-Helfer benötigt. Neue Filter starten mit leerer Eintragsliste, 200 × 50 px und nur CSS Allgemein aktiv. Bestehende einfache Listen bleiben verwendbar.</p><h3 id="bar" tabindex="-1">Bar <a class="header-anchor" href="#bar" aria-label="Permalink to &quot;Bar&quot;">​</a></h3><p><img src="'+a+'" alt="Umgekehrter blauer Balken mit Rand- und Schatteneinstellungen"></p><p><em>Frühere Testansicht: Der umgekehrte Balken wächst von rechts. CSS Allgemein bleibt heute verpflichtend aktiv.</em></p><p><a href="/images/grafik-visual-studio/bar.png">Bild in voller Größe öffnen</a></p><p><strong>Bar</strong> zeigt einen Zahlenwert innerhalb von <strong>Minimum</strong> und <strong>Maximum</strong> als farbigen Balken. Bei 0–1000 entspricht 300 einem Füllstand von 30 %. Werte außerhalb des Bereichs werden auf 0–100 % begrenzt; bei gleichem Minimum und Maximum bleibt der Balken leer. Eine HA-Sensorentität wie Solarleistung passt hier: Das Widget liest nur und benötigt keinen zusätzlichen Helfer.</p><p>Horizontal wächst der Balken von links, vertikal von oben. <strong>Wert umkehren</strong> wechselt den Ursprung zu rechts beziehungsweise unten; 30 % bleiben dabei 30 %. <strong>Rand</strong> erwartet CSS, etwa <code>2px solid blue</code>; die einzelne <code>2</code> aus dem Export ist keine vollständige Randdefinition. <strong>Durchsichtigkeit (Schatten/CSS)</strong> entspricht dem VIS2-Feld <code>shadow</code> und erwartet einen CSS-Schatten wie <code>2px 2px 4px #0008</code>, keinen Transparenzwert. Alte gespeicherte Studio-Deckkraftwerte bleiben wirksam.</p><p>Neue Balken starten blau, horizontal, mit 0–100, 200 × 130 px und ausschließlich aktiviertem CSS Allgemein. Umsteigerhinweise erklären die Felder und sind über <strong>Umsteigerhinweise anzeigen</strong> abschaltbar. Der optionale Ausgangspunkt bleibt verfügbar.</p><h3 id="html-state" tabindex="-1">HTML State <a class="header-anchor" href="#html-state" aria-label="Permalink to &quot;HTML State&quot;">​</a></h3><p><img src="'+d+'" alt="HTML State mit festem Wert und Umsteigerhinweisen"></p><p><em>Das Beispiel zeigt Hallo und sendet off; die kleinen Hinweise erklären Schreibziele und Browser-URL-Aufrufe.</em></p><p><strong>HTML</strong> ist der angezeigte Inhalt. <strong>Wert</strong> ist ein fester Schreibwert: Bei jedem Klick wird derselbe Wert gesendet, unabhängig vom aktuellen Zustand. Dein Beispiel mit <code>Hallo</code> und <code>off</code> zeigt „Hallo“ und sendet bei jedem Klick einen Aus-Befehl an eine passende schaltbare HA-Entität. Ein Sensor ist kein Schreibziel. Zahlen benötigen einen passenden <code>input_number</code>-Helfer, Text einen <code>input_text</code>-Helfer; <code>switch</code>, <code>light</code> und <code>input_boolean</code> unterstützen passende Ein-/Aus-Werte. Nicht verfügbare oder ungeeignete Ziele werden nicht beschrieben.</p><p><strong>Rufe URL bei Klick</strong> sendet optional einen HTTP(S)-GET-Aufruf vom Browser. Die Ansicht bleibt geöffnet. Dieser Aufruf funktioniert auch ohne HA-Schreibziel und wird nicht über einen ioBroker-Server ausgeführt; Browserregeln, HTTPS und Netzwerkzugriff gelten weiterhin. Eine undurchsichtige Browserantwort bestätigt nicht den Erfolg des Zielsystems. Im Editor werden weder Werte geschrieben noch URLs aufgerufen. In der Runtime sind Klick, Enter und Leertaste möglich.</p><p>Neue Widgets beginnen mit leeren Feldern und ausschließlich aktiviertem CSS Allgemein. Bisherige Inhalte bleiben erhalten; der alte Vorschauwert wird als fester Wert übernommen, solange kein neuer <strong>Wert</strong> gesetzt ist. HTML wird bereinigt angezeigt; <code>{value}</code> ist hier kein Platzhalter. Umsteigerhinweise an Entität und URL lassen sich zentral in den Einstellungen abschalten.</p><h3 id="umsteigerhinweise" tabindex="-1">Umsteigerhinweise <a class="header-anchor" href="#umsteigerhinweise" aria-label="Permalink to &quot;Umsteigerhinweise&quot;">​</a></h3><p><img src="'+l+'" alt="Abschaltbarer roter Umsteigerhinweis unter einer Entität"></p><p><em>Bool-Select-Beispiel mit Hinweis unter der Entitätsauswahl. Diese Editorhinweise lassen sich zentral abschalten.</em></p><p>Unter <strong>Einstellungen → Allgemein → Umsteigerhinweise anzeigen</strong> lassen sich die Hinweise zentral ein- und ausschalten. Die Auswahl wird pro Projekt gespeichert; standardmäßig sind sie aktiv. Sie stehen direkt unter betroffenen Editorfeldern und erklären passende HA-Schaltziele oder Helfer, JSON-/Indexquellen und noch nicht angebundene Extrasteuerung. Reine Anzeige benötigt keinen zusätzlichen Schreibhelfer. Die Texte sind 10 px groß, ohne Fettdruck, hellrot auf dunklem beziehungsweise dunkelrot auf hellem Editorhintergrund. In der Runtime erscheinen sie nicht.</p><h3 id="table" tabindex="-1">Table <a class="header-anchor" href="#table" aria-label="Permalink to &quot;Table&quot;">​</a></h3><p><img src="'+o+'" alt="Tabelle mit den Spalten Title und Value"></p><p><em>Static-JSON-Beispiel: Die Metadaten _Description erscheinen nicht in den beiden sichtbaren Spalten.</em></p><p><strong>Static JSON (ohne ID)</strong> enthält ein Array von Zeilenobjekten. Eine gebundene HA-Entität liefert stattdessen ihren JSON-Zustand in der Runtime. Beim Beispiel <code>[{&quot;Title&quot;:&quot;first&quot;,&quot;Value&quot;:1,&quot;_Description&quot;:&quot;Value1&quot;},{&quot;Title&quot;:&quot;second&quot;,&quot;Value&quot;:2,&quot;_Description&quot;:&quot;Value2&quot;}]</code> erscheinen die Spalten <strong>Title</strong> und <strong>Value</strong>. Attribute mit <code>_</code> bleiben als Metadaten verborgen; <code>_btn…</code> erzeugt eine Bestätigungsschaltfläche. Zellen dürfen HTML enthalten, das vor der Anzeige bereinigt wird.</p><p><strong>Kolumnanzahl</strong> blendet Einstellungen für Spaltentitel, CSS-Breite und Attributzuordnung ein. Eine ausdrückliche Attributzuordnung kann auch Metadaten anzeigen. <strong>Kein Header</strong>, <strong>Zeige Scrollbar</strong> und <strong>Maximale Zeilenanzahl</strong> steuern die Darstellung. Neue Tabellen starten mit nur CSS Allgemein aktiviert. Ein Druckbutton erscheint erst mit einem Text in <strong>btn_print</strong>; <strong>view_for_print</strong> wählt optional die Druckseite.</p><p><strong>Ereignis ID</strong> liest einzelne JSON-Zeilen. Der anfänglich vorhandene Zustand wird nicht als neues Ereignis übernommen. Änderungen ergänzen die Ereignisliste; gleiche <code>_id</code> ersetzen eine vorhandene Ereigniszeile. <strong>Neues Ereignis am Anfang</strong> gilt für diese Ereignisliste und dreht die Grundtabelle nicht um. Ereignisse und Auswahl gelten für die laufende Runtime-Sitzung.</p><p>Eine Zeilenauswahl schreibt das Zeilenobjekt als JSON in <strong>Ausgewählt ID</strong> (<code>input_text</code>) und zeigt <code>_detail</code> im <strong>Detailed widget</strong>. Bestätigungsbuttons schreiben <code>_ack_id</code> oder das Zeilenobjekt in <strong>Bestätigung ID</strong>. HA-Ziele müssen verfügbare, passende Zahlen-/Texthelfer sein; deren Typ- und Längenlimits gelten weiterhin. Im Editor werden keine HA-Werte geschrieben.</p><h3 id="bool-select" tabindex="-1">Bool Select <a class="header-anchor" href="#bool-select" aria-label="Permalink to &quot;Bool Select&quot;">​</a></h3><p><img src="'+g+'" alt="Bool Select mit ausgewähltem Zustand Läuft"></p><p><em>Runtime-Beispiel mit vorangestelltem Tor: und ausgewähltem Text Läuft.</em></p><p>Das Auswahlfeld hat zwei Einträge mit <strong>Text bei &#39;false&#39;</strong> und <strong>Text bei &#39;true&#39;</strong>. Es liest boolesche und numerische Zustände: <code>0</code> gilt als false, andere Zahlen als true. HA-Zustände <code>off</code>/<code>on</code> werden passend zugeordnet. <strong>HTML voranstellen</strong>, <strong>HTML anhängen</strong> und <strong>Autofokus</strong> sind vorhanden; Autofokus gilt nur in der Runtime.</p><p>Eine Auswahl schreibt <code>0</code> oder <code>1</code> in einen passenden <code>input_number</code>- oder <code>input_text</code>-Helfer. Bei <code>switch</code>, <code>light</code> und <code>input_boolean</code> wird ein entsprechender HA-Schaltbefehl gesendet. Ungeeignete oder nicht verfügbare Ziele sind gesperrt. Ohne Entität ist eine lokale Runtime-Vorschau möglich; im Editor wird nicht geschrieben. Neue Widgets starten mit leeren Text-/HTML-Feldern, deaktiviertem Autofokus und ausschließlich aktiviertem CSS Allgemein. Bestehende Beschriftungen bleiben erhalten.</p><h3 id="bool-svg" tabindex="-1">Bool SVG <a class="header-anchor" href="#bool-svg" aria-label="Permalink to &quot;Bool SVG&quot;">​</a></h3><p><img src="'+u+'" alt="Bool SVG mit Stern-Motiv und Nur Anzeige"></p><p>Unter <strong>Allgemein</strong> stehen die HA-Entität, <strong>Nur Anzeige</strong>, <strong>SVG bei false</strong>, <strong>SVG bei true</strong> und <strong>Durchsichtigkeit</strong>. Die SVG-Felder lassen sich im Code-Editor bearbeiten. Neue Widgets sind 85 × 85 px groß und verwenden die beiden Stern-Motive der VIS2-Vorlage. SVG-Koordinaten und eigene <code>transform</code>-Angaben bleiben erhalten; die Widgetgröße skaliert den Inhalt nicht automatisch.</p><p><code>false</code>, <code>off</code> und numerische Null wählen das false-Motiv; Zahlen ungleich Null das true-Motiv. Beim Schalten numerischer Werte gilt der VIS2-Schwellwert 0,5: darunter wird 1, ab 0,5 wird 0 geschrieben. Schaltbare HA-Entitäten erhalten Ein/Aus; Zahlen- oder Textwerte benötigen einen passenden <code>input_number</code>-/<code>input_text</code>-Helfer. <strong>Nur Anzeige</strong> verhindert das Schreiben, auch Sensoren können dann als Quelle dienen. Im Editor wird niemals geschaltet.</p><p>Die Durchsichtigkeit reicht von 0 bis 1. Im Editor bleiben mindestens 20 % sichtbar, damit das Widget bearbeitbar bleibt; in der Runtime gilt auch vollständige Transparenz. <strong>CSS Allgemein</strong> ist für Position und Größe aktiv, die übrigen CSS-Gruppen sind bei neuen Widgets deaktiviert. Die optionalen Umsteigerhinweise erklären die Schreibziele und das Verhalten der Durchsichtigkeit.</p><h3 id="red-number" tabindex="-1">Red Number <a class="header-anchor" href="#red-number" aria-label="Permalink to &quot;Red Number&quot;">​</a></h3><p><img src="'+h+'" alt="Red Number mit HTML-Vortext und benutzerdefinierten Farben"></p><p><em>Vergrößerte Beispielanzeige mit lokalem Vorschauwert 125; Standardgröße neuer Widgets ist 52 × 30 px.</em></p><p>Neue Widgets beginnen mit 52 × 30 px. <strong>Allgemein</strong> bietet die HA-Entität, <strong>type</strong> (Kreis/Pin), drei HTML-Felder mit Code-Editor, Hintergrund und beim Kreis zusätzlich Randfarbe sowie Grenzradius (0–100, Standard 16). Der Kreis verwendet einen 3-px-Rand; der Pin zeigt eine Markierungsform ohne Kreisrand. Farben werden über HEX-Farbwähler eingestellt; bestehende RGB(A)-Farben bleiben darstellbar.</p><p><strong>HTML voranstellen</strong> steht vor der Zahl. Bei genau 1 gilt <strong>HTML anhängen (Singular)</strong>, sonst <strong>HTML anhängen (Plural)</strong>. Der Zahlenwert wird aus dem Zustand gelesen. In der Runtime wird die Anzeige bei 0, false oder fehlendem gültigen Zahlenwert ausgeblendet. Im Editor bleibt sie sichtbar; ohne Quelle erscheint <code>--</code>. Lange HTML-Texte benötigen eine entsprechend größere Widgetfläche.</p><p>Das Widget liest nur und benötigt keinen zusätzlichen HA-Helfer. Der vorhandene Ausgangspunkt bleibt als Wertquelle nutzbar, auch wenn die Null-Anzeige ausgeblendet ist. <strong>CSS Allgemein</strong> bleibt aktiv, übrige CSS-Gruppen starten deaktiviert. Der optionale Umsteigerhinweis erklärt das Ausblenden.</p><h3 id="svg-shape" tabindex="-1">SVG shape <a class="header-anchor" href="#svg-shape" aria-label="Permalink to &quot;SVG shape&quot;">​</a></h3><p><img src="'+c+'" alt="SVG shape mit Kreis und getrennten Skalierungsreglern"></p><p>Die Form wird direkt als SVG gezeichnet; Bilddateien, HA-Entitäten oder zusätzliche Helfer werden nicht benötigt. Neue Widgets sind <strong>100 × 100 px</strong> groß. Unter <strong>Allgemein</strong> stehen Linie, Dreieck, Quadrat, Pentagon, Sechseck, Achteck, Kreis, Stern, Pfeil und benutzerdefiniertes Polygon zur Auswahl. Beim benutzerdefinierten Polygon wird zusätzlich die <strong>Punkteanzahl</strong> von 3 bis 20 angeboten; sie erzeugt ein regelmäßiges Polygon, keine frei eingegebenen Koordinaten.</p><p><strong>Linienfarbe</strong> und <strong>Füllfarbe</strong> werden als HEX gewählt. Die <strong>Linienbreite</strong> reicht von 0 bis 100 (Standard 5), <strong>Drehen</strong> von 0 bis 360 Grad. <strong>Breitenskala</strong> und <strong>Höhenskala</strong> sind getrennt von 0 bis 1 in Schritten von 0,05 einstellbar. Drehung und Skalierung erfolgen um die Formmitte; bei der Linie gilt wie im VIS2-Vorbild nur die Drehung, ihre Strichbreite wird beim Vergrößern nicht mitskaliert.</p><p>Der Stern verwendet sich kreuzende Kanten, der Pfeil zeigt ohne Drehung nach oben. Die Strichbreite verkleinert den verfügbaren Radius von Kreis und Polygonen. Sehr breite Striche können kleine Formen vollständig ausfüllen; negative Radien werden verhindert. <strong>CSS Allgemein</strong> bleibt für Position und Größe aktiv; alle übrigen CSS-Gruppen sind bei neuen Widgets deaktiviert. Editor und Runtime zeichnen dieselbe Geometrie.</p><h3 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to &quot;Image&quot;">​</a></h3><p><strong>Allgemein</strong> enthält Quelle, Strecken, Updatezeit (ms), Update bei Aufwachen, Update bei Viewwechsel, Addiere nichts zu URL und <code>allowUserInteractions</code>. <strong>CSS Allgemein</strong> bleibt aktiv; andere CSS-Gruppen starten deaktiviert.</p><ul><li>Ohne <strong>Strecken</strong> verwendet das Bild die volle Widget-Breite mit seinem ursprünglichen Seitenverhältnis. Überstehende Höhe wird abgeschnitten. Mit Strecken füllt es Breite und Höhe, auch wenn sich dadurch das Seitenverhältnis ändert.</li><li><strong>Updatezeit 0</strong> deaktiviert regelmäßiges Neuladen. Beispielsweise aktualisiert <code>51800</code> alle 51,8 Sekunden. Unveränderte Bilder werden durch andere Zustandswechsel nicht neu geladen; laufende Timer behalten ihren Takt. Unsichtbare Bilder werden nicht regelmäßig aktualisiert.</li><li><strong>Update bei Aufwachen / Viewwechsel</strong> lädt beim erneuten Aktivieren der Browserseite beziehungsweise beim Öffnen der Projektseite nach. <strong>Addiere nichts zu URL</strong> behält die URL unverändert; dabei kann der Browser seinen Cache verwenden. Ohne Haken ergänzt Studio einen Zeitstempel und erhält vorhandene URL-Parameter und Sprungmarken.</li><li><strong>allowUserInteractions</strong> erlaubt normale Browseraktionen wie Ziehen oder das Bild-Kontextmenü in der Runtime. Ohne Haken werden Zeigeraktionen zum darunterliegenden Element durchgereicht. Im Editor bleibt das Widget auswählbar und verschiebbar.</li></ul><p>Bild über die Studio-Dateiauswahl oder eine URL wählen. VIS2-Pfade wie <code>_PRJ_NAME/001_cheerful.png</code> müssen durch den entsprechenden Studio-Dateipfad ersetzt werden. Kein HA-Helfer nötig. Bestehende Projekte mit einer URL-Entität werden weiterhin gelesen; eine HA-Kamera-API wird dadurch nicht angebunden. Die kleinen roten Umsteigerhinweise sind über die zentrale Einstellung ein- und ausschaltbar.</p><p><img src="'+b+'" alt="Image mit Strecken und proportionaler Darstellung im Vergleich"></p><p>Funktionale Referenz: <a href="https://github.com/ioBroker/ioBroker.vis-2/blob/master/packages/iobroker.vis-2/src-vis/src/Vis/Widgets/Basic/BasicImage.tsx" target="_blank" rel="noreferrer">VIS2 Image</a>.</p><h3 id="image-8" tabindex="-1">Image 8 <a class="header-anchor" href="#image-8" aria-label="Permalink to &quot;Image 8&quot;">​</a></h3><p>Die HA-Entität liefert den Bildindex; <code>false</code>/<code>off</code> entspricht 0, <code>true</code>/<code>on</code> entspricht 1. Ohne Entität oder bei einem fehlenden Zustand wird <strong>Bild [0]</strong> verwendet. Die Entität wird im Editor und in der Runtime nur gelesen; ein zusätzlicher HA-Helfer ist nicht nötig.</p><p><strong>Werteanzahl bis</strong> bezeichnet den höchsten Index und ist auf <strong>200</strong> begrenzt: 0 ergibt einen Eintrag, 200 ergibt <strong>201 Einträge von Bild [0] bis Bild [200]</strong>. Jede Bildgruppe besitzt eine Quelle mit Dateiauswahl und kann kopiert, gelöscht, verschoben oder deaktiviert werden. Der letzte Eintrag bleibt erhalten; bei Index 200 ist Kopieren deaktiviert. Leere, deaktivierte oder ungültige Indizes zeigen kein Bild; vorhandene Quellen werden nicht automatisch neu nummeriert. Beim Verringern der Grenze bleiben die ausgeblendeten Quellen erhalten, bis sie ausdrücklich gelöscht werden.</p><p>Neue Widgets sind <strong>200 × 130 px</strong> groß. Strecken, Updatezeit, Aufwachen, Viewwechsel, unveränderte URL und normale Browseraktionen entsprechen <strong>Image</strong>. Ein unverändertes Bild wird bei anderen Zustandsänderungen nicht neu geladen; laufende Refresh-Timer behalten ihren Takt. <strong>CSS Allgemein</strong> bleibt aktiv, andere CSS-Gruppen starten deaktiviert. Die kleinen roten Umsteigerhinweise lassen sich zentral ein- und ausschalten.</p><p><img src="'+m+'" alt="Image 8 mit höchstem Bildindex 200 und Refresh-Einstellungen"></p><p>Funktionale Referenz: <a href="https://github.com/ioBroker/ioBroker.vis-2/blob/master/packages/iobroker.vis-2/src-vis/src/Vis/Widgets/Basic/BasicImage8.tsx" target="_blank" rel="noreferrer">VIS2 Image 8</a>.</p><h3 id="iframe" tabindex="-1">iFrame <a class="header-anchor" href="#iframe" aria-label="Permalink to &quot;iFrame&quot;">​</a></h3><p><img src="'+p+'" alt="iFrame mit eingebetteter UGSo-Website und Aktualisierungsoptionen"></p><p>Neue Widgets haben <strong>600 × 320 px</strong>. Unter <strong>Allgemein</strong> stehen Quelle, Updatezeit (ms), Kein Sandkasten, Update bei Aufwachen, Update bei Viewwechsel, Addiere nichts zu URL, Scroll X/Y und Kein Rahmen. <strong>CSS Allgemein</strong> bleibt aktiv; die übrigen CSS-Gruppen starten deaktiviert. Im Editor lässt sich das Widget auswählen und verschieben, ohne dass die eingebettete Seite die Mausbedienung übernimmt.</p><p><strong>Updatezeit 0</strong> deaktiviert regelmäßiges Neuladen. Werte bis 180000 ms aktivieren ein Intervall. <strong>Update bei Aufwachen</strong> lädt nach Rückkehr zum sichtbaren Browserfenster neu; <strong>Update bei Viewwechsel</strong> gilt beim Anzeigen der Studio-Seite. Änderungen anderer Widgetwerte laden eine unveränderte Einbettung nicht neu. Ohne <strong>Addiere nichts zu URL</strong> ergänzt eine Aktualisierung den Zeitstempelparameter <code>_gvs</code>; vorhandene URL-Parameter und Sprungmarken bleiben erhalten. Mit Haken wird dieselbe URL erneut geladen.</p><p>Standardmäßig beschränkt eine Sandbox die eingebettete Seite auf Skripte und Formulare. <strong>Kein Sandkasten</strong> entfernt diese Einschränkung. Anmeldung, Cookies und Einbettungsregeln der Zielseite gelten weiterhin; eine Seite kann die Einbettung per Browserrichtlinie verweigern. Scroll X/Y setzen die gewünschten Überlaufoptionen, die tatsächlich verfügbaren Scrollleisten hängen auch vom Browser und Inhalt der Zielseite ab. Bei fremden Domains kann Studio deren interne Scrollachsen nicht erzwingen. <strong>Kein Rahmen</strong> entfernt den iFrame-Rand.</p><p>Es wird kein HA-Zustand geschrieben und kein HA-Helfer benötigt. Die optionalen Umsteigerhinweise erklären Sandbox und Aktualisierung. Ein iFrame verweist auch nach einem Export auf seine Quelle; die fremde Website wird nicht als lokale Kopie eingebettet.</p><h3 id="iframe-8" tabindex="-1">iFrame 8 <a class="header-anchor" href="#iframe-8" aria-label="Permalink to &quot;iFrame 8&quot;">​</a></h3><p><img src="'+k+'" alt="iFrame 8 mit URL und Sandbox je Eintrag"></p><p><em>Editor-Beispiel mit lokaler SVG-URL für Frame [0].</em></p><p>Die zustandsabhängige Variante verwendet die HA-Entität als URL-Index. <code>false</code>/<code>off</code> wählen [0], <code>true</code>/<code>on</code> wählen [1]; Zahlen wählen den entsprechenden nummerierten Eintrag. Ohne Entität starten neue Widgets mit Frame [0]. Ungültige, negative oder zu große Indizes sowie leere oder deaktivierte Einträge zeigen keinen Frame. Die Entität wird nur gelesen; ein zusätzlicher HA-Helfer ist nicht nötig.</p><p><strong>Werteanzahl bis</strong> ist der höchste Index, nicht die Anzahl: Standard 2 ergibt [0], [1], [2]; Maximum 20 ergibt <strong>21 Einträge von [0] bis [20]</strong>. Die Gruppen <strong>frames [n]</strong> enthalten <strong>URL falls Wert [n]</strong> und <strong>Kein Sandkasten [n]</strong>. Sie können aktiviert/deaktiviert, kopiert, gelöscht und umgeordnet werden. Beim Reduzieren der höchsten Nummer bleiben ausgeblendete Einträge erhalten. Die Nummern entsprechen direkt dem Entitätswert; Umordnen verändert diese Zuordnung.</p><p>Standardgröße ist <strong>600 × 320 px</strong>. Aktualisierungsintervall, Aufwachen, Viewwechsel, unveränderte URL, Scroll X/Y und Rahmen funktionieren wie bei <strong>iFrame</strong>. Die Sandbox wird je Eintrag gewählt. Eine unveränderte URL mit unveränderter Sandbox wird bei Änderungen anderer Widgets nicht erneut geladen. Bei anderer URL oder Sandbox wird die Einbettung ersetzt. <strong>CSS Allgemein</strong> bleibt aktiv; die übrigen CSS-Gruppen starten deaktiviert. Die optionalen Umsteigerhinweise erklären Index, Sandbox und Aktualisierung.</p><h3 id="note" tabindex="-1">Note <a class="header-anchor" href="#note" aria-label="Permalink to &quot;Note&quot;">​</a></h3><p><strong>Allgemein</strong> enthält Home-Assistant-Entität, HA-Attribut, HTML voranstellen, HTML anhängen, Testtext und Ecke ausblenden. Das zusätzliche Attributfeld ersetzt ioBroker-Attributdatenpunkte: Für <code>friendly_name</code> die passende HA-Entität wählen und <code>friendly_name</code> eintragen. Ein leeres Attributfeld liest den Zustand.</p><p>Ein nicht leerer <strong>Testtext</strong> ersetzt im Editor den Entitätswert. In der Runtime wird ausschließlich der Entitätswert beziehungsweise das Attribut angezeigt; fehlt er, bleibt der mittlere Text leer. Voranstellen und Anhängen bleiben sichtbar. Wie im VIS2-Note-Quellcode werden auch die als HTML bezeichneten Felder als Text dargestellt; <code>&lt;b&gt;</code> erzeugt hier keine Fettschrift. Zeilenumbrüche bleiben erhalten.</p><p><strong>Ecke ausblenden</strong> steuert nur die untere rechte Ecke und ist kein Schreibschutz. Ohne Haken zeigt sie die Rahmenfarbe. Neue Notizen sind <strong>100 × 70 px</strong> groß, mit 5 px Eckenradius, grauem 1 px Rahmen und gelbem Hintergrund <code>#FFFF69CC</code>. Größe und Farben bleiben über CSS anpassbar; <strong>CSS Allgemein</strong> bleibt aktiv, andere CSS-Gruppen starten deaktiviert.</p><p>Ein Klick in der Runtime öffnet den Notizdialog. Ein verfügbarer <strong>input_text-Helfer ohne Attributauswahl</strong> erlaubt Bearbeiten, Leeren und Übernehmen; seine maximale Textlänge wird beachtet. Geschrieben wird nur der Notiztext, ohne Voranstellen und Anhängen. Sensoren und Attribute bleiben lesbar, bieten aber kein Schreibziel. Ohne passendes Schreibziel ist das Textfeld im Dialog nur lesbar und Übernehmen deaktiviert. Abbrechen und Escape schließen den Dialog ohne Schreiben. Die kleinen roten Helferhinweise lassen sich über <strong>Umsteigerhinweise anzeigen</strong> ein- und ausschalten.</p><p><img src="'+f+'" alt="Note mit Testtext und Vergleich der ausgeblendeten und sichtbaren Ecke"></p><p>Funktionale Referenz: <a href="https://github.com/ioBroker/ioBroker.vis-2/blob/master/packages/iobroker.vis-2/src-vis/src/Vis/Widgets/Basic/BasicNote.tsx" target="_blank" rel="noreferrer">VIS2 Note</a>.</p><h3 id="horizontal-line-vertical-line" tabindex="-1">Horizontal line / Vertical line <a class="header-anchor" href="#horizontal-line-vertical-line" aria-label="Permalink to &quot;Horizontal line / Vertical line&quot;">​</a></h3><p>Die zwei Trennlinien sind reine Anzeige und benötigen keinen HA-Helfer. Horizontal line startet mit <strong>200 × 16 px</strong>, Vertical line mit <strong>16 × 200 px</strong>. Unter <strong>CSS Trennlinie</strong> stehen Dicke (1–100 px, Standard 2), HEX-Farbe, Rahmenfarbe, Rahmenbreite und Enden zur Verfügung: <strong>Eckig</strong> (Standard), <strong>Rund</strong> oder <strong>Spitz (pfeilartig)</strong> an beiden Enden. Eine erhöhte Dicke vergrößert bei Bedarf die Querabmessung des Widgets; beim anschließenden Verkleinern begrenzt die Widgetfläche die sichtbare Dicke.</p><p>Ab <strong>0.1.183</strong> besitzen die Trennlinien keine <strong>Andockpunkte</strong> und keinen <strong>Datenfluss</strong>. <strong>Snapfunktion aktivieren</strong> unter <strong>CSS Trennlinie</strong> schaltet das geometrische Einrasten zu; bei neuen Linien ist es ausgeschaltet. Bereits aktivierte Snap-Einstellungen bleiben erhalten. Beim einzelnen Ziehen, Skalieren eines Linienendes oder Bearbeiten der Geometrie werden Enden innerhalb von <strong>8 Seitenpixeln</strong> auf die Mitte einer rechtwinkligen Trennlinie gesetzt. Das funktioniert an beliebigen Stellen entlang der anderen Linie, auch für T-Verbindungen. Parallel verlaufende Linien rasten nicht ein. Gemeinsames Verschieben mehrerer Widgets verändert ihre relativen Abstände nicht. Frei gesetzte CSS-Positionen/-Größen und CSS-Transformationen deaktivieren das Einrasten.</p><p>Gespeichert werden die tatsächlichen Koordinaten und die Liniengestaltung, auch im Widget- und Projekt-Export. Die Verbindung ist keine dauerhafte Bindung: Wird eine Linie später wegbewegt, folgt die andere nicht automatisch. <strong>CSS Allgemein</strong> und <strong>CSS Trennlinie</strong> bleiben für das Speichern aktiv. Der optionale Umsteigerhinweis folgt der zentralen Einstellung <strong>Umsteigerhinweise anzeigen</strong>.</p><p><img src="'+S+'" alt="Trennlinien mit T-Verbindung, pfeilartigen Enden und CSS-Einstellungen"></p><p><img src="'+w+'" alt="Aktivierte Snapfunktion ohne Andockpunkte und Datenfluss im Trennlinien-Editor"></p><p><em>Die Snapfunktion verbindet an beliebigen Stellen der jeweils anderen Trennlinie. Alte Dock- und Datenflusseinstellungen werden beim Laden und Speichern entfernt.</em></p><h3 id="border" tabindex="-1">Border <a class="header-anchor" href="#border" aria-label="Permalink to &quot;Border&quot;">​</a></h3><p>Border zeichnet einen Rahmen mit Titel und optionalem Kopfbereich. Neue Widgets sind <strong>100 × 70 px</strong> groß, mit einem grauen (<code>#888888</code>) Rahmen von 1 px und sichtbarem Überlauf. <strong>Allgemein</strong> enthält die sechs Standardfelder: Titel, Titelhintergrund, Titel-Oben-Abstand, Titel-Links-Abstand, Kopfhöhe und Kopffarbe. Farben werden als HEX gewählt.</p><p>Die Titelposition ist absolut zum Rahmen: Standard <strong>oben −10 px, links 20 px</strong>, ohne zusätzliche vertikale Verschiebung. Der Titel darf einfache HTML-Formatierungen wie <code>&lt;b&gt;Titel&lt;/b&gt;</code> enthalten; Skripte, Event-Handler und aktive Einbettungen werden entfernt. Schrift und Rahmen lassen sich über die passenden CSS-Gruppen gestalten.</p><p><strong>Kopfhöhe 0</strong> blendet den Kopfbereich aus. Ohne eigenen Titelhintergrund erhält der Titel dann eine schwarze Fläche im dunklen beziehungsweise eine weiße Fläche im hellen Seitenthema. Bei sichtbarem Kopfbereich bleibt der Titelhintergrund ohne eigene Farbe transparent; eine leere Kopffarbe verwendet ebenfalls Schwarz oder Weiß passend zum Thema. Im Beispiel links ist nur der Titelhintergrund gesetzt, rechts zusätzlich ein 30 px hoher Kopfbereich.</p><p>Rahmen und Titel benötigen keine HA-Entität und keinen Helfer. <strong>CSS Allgemein</strong> bleibt für Position und Größe aktiv; die anderen CSS-Gruppen starten deaktiviert. Optionale kleine rote Umsteigerhinweise lassen sich zentral ein- und ausschalten.</p><p><img src="'+z+'" alt="Border mit Titelposition und optionalem Kopfbereich"></p><p>Funktionale Referenz: <a href="https://github.com/ioBroker/ioBroker.vis-2/blob/master/packages/iobroker.vis-2/src-vis/src/Vis/Widgets/Basic/BasicFrame.tsx" target="_blank" rel="noreferrer">VIS2 Border</a>.</p><h3 id="bool-checkbox" tabindex="-1">Bool Checkbox <a class="header-anchor" href="#bool-checkbox" aria-label="Permalink to &quot;Bool Checkbox&quot;">​</a></h3><p>Die Checkbox zeigt den Zustand der gebundenen Home-Assistant-Entität. In der Runtime kann sie <code>switch</code>, <code>light</code> und <code>input_boolean</code> schalten; ohne verfügbare, passende Entität ist sie gesperrt. Im Editor dient sie nur als Vorschau.</p><p><strong>HTML voranstellen</strong> und <strong>HTML anhängen</strong> ergänzen die Checkbox um Text oder HTML. <strong>Autofokus</strong> gilt nur in der Runtime. Neue Widgets beginnen mit leeren HTML-Feldern, deaktiviertem Autofokus und ausschließlich aktiviertem CSS Allgemein. Bestehende Einstellungen bleiben erhalten.</p><h3 id="bool-html" tabindex="-1">Bool HTML <a class="header-anchor" href="#bool-html" aria-label="Permalink to &quot;Bool HTML&quot;">​</a></h3><p><img src="'+v+'" alt="Bool HTML mit Editoren für true und false"></p><p><em>Frühere Testansicht der vier HTML-Felder. CSS Allgemein bleibt heute verpflichtend aktiv.</em></p><p>Ab <strong>0.1.146</strong> stehen <strong>HTML voranstellen</strong>, <strong>HTML anhängen</strong>, <strong>HTML bei &#39;false&#39;</strong> und <strong>HTML bei &#39;true&#39;</strong> zur Verfügung, jeweils mit HTML-Editor. Der Entitätszustand wählt den Inhalt; ohne Entität dient <strong>Testzustand</strong> als Vorschau. Boolean <code>true</code>, Zahl <code>1</code> sowie die Texte <code>true</code>, <code>on</code>, <code>ein</code>, <code>yes</code> und <code>1</code> wählen den true-Inhalt; andere Zustände wählen false. Vorangestelltes und angehängtes HTML erscheinen unabhängig davon. Die Studio-HTML-Bereinigung gilt für alle vier Felder.</p><p>Neue Widgets beginnen mit leeren HTML-Feldern und ausschließlich aktiviertem CSS Allgemein. Bereits konfigurierte Inhalte bleiben erhalten. <strong>Bool HTML</strong> zeigt nur an und schaltet keine Entität; dafür gibt es <strong>Bool HTML (control)</strong>.</p><h3 id="valuelist-html" tabindex="-1">ValueList HTML <a class="header-anchor" href="#valuelist-html" aria-label="Permalink to &quot;ValueList HTML&quot;">​</a></h3><p>Ab <strong>0.1.144</strong> wählt <strong>Testwert (nur Editor)</strong> einen Index aus den vorhandenen Listeneinträgen. <strong>Livewert / Vorschauzustand</strong> zeigt auch im Editor den normalen Widgetzustand. Ein Testwert ändert weder den gespeicherten Vorschauzustand noch den HA-Wert; die Runtime verwendet immer den gebundenen Entitätszustand beziehungsweise den ungebundenen Vorschauzustand.</p><p>Trenne Einträge mit Semikolon oder Zeilenumbrüchen: <code>Test;test2;test3</code> ergibt die Indizes 0, 1 und 2. Kommas bleiben Teil des Textes: <code>Test, test2, test3</code> ist ein Eintrag. Schreibe ein Semikolon innerhalb eines HTML-Eintrags als <code>§§</code>, etwa in einem CSS-Stil oder einer HTML-Entität. <strong>HTML voranstellen</strong> und <strong>HTML anhängen</strong> umgeben den ausgewählten Eintrag; HTML wird nach den Studio-Regeln bereinigt. Fehlende, ungültige oder außerhalb der Liste liegende Zustände zeigen keinen Listeneintrag. Neue ValueList-HTML-Widgets haben nur CSS Allgemein standardmäßig aktiviert; bestehende Einstellungen bleiben erhalten.</p><h3 id="valuelist-html-style" tabindex="-1">ValueList HTML Style <a class="header-anchor" href="#valuelist-html-style" aria-label="Permalink to &quot;ValueList HTML Style&quot;">​</a></h3><p>Ab <strong>0.1.145</strong> bietet das Widget einzelne Bereiche <strong>Wert [0]</strong> bis <strong>Wert [n]</strong> mit HTML-Inhalt und zugehörigem CSS-Stil. <strong>Werteanzahl bis</strong> ist der höchste Index: <code>2</code> ergibt drei Einträge, <code>0</code> genau einen. Studio erlaubt maximal Index 50. Vorhandene Listenfelder aus älteren Projekten dienen weiterhin als Fallback.</p><p><strong>Testwert (nur Editor)</strong> wählt einen Eintrag ausschließlich für die Vorschau. Die Runtime liest den Index aus der gebundenen Entität oder dem ungebundenen Vorschauzustand; <code>true</code> und <code>false</code> entsprechen 1 und 0. Der Index ist kein Messwertbereich: Bei Einträgen <code>10</code>, <code>20</code>, <code>30</code> zeigt Zustand <code>2</code> den Text <code>30</code>; Zustand <code>30</code> liegt außerhalb einer Liste bis Index 2 und zeigt keinen Eintrag.</p><p>Der Stil gilt auch für das vorangestellte und angehängte HTML. Verwende vollständige CSS-Deklarationen, zum Beispiel <code>font-weight: bold; color: #29c8b5; font-size: 20px;</code>. <code>bold</code> allein hat keine Wirkung. Studio akzeptiert die freigegebenen Darstellungsstile ohne externe CSS-URLs. Bei neuen Widgets ist nur CSS Allgemein standardmäßig aktiviert; die Stile der einzelnen Werte bleiben davon unabhängig nutzbar.</p><h3 id="view-in-widget-8" tabindex="-1">View in widget 8 <a class="header-anchor" href="#view-in-widget-8" aria-label="Permalink to &quot;View in widget 8&quot;">​</a></h3><p>Seit <strong>0.1.160</strong> bettet dieses Widget abhängig vom Zustand einer HA-Entität eine <strong>Studio-Projektseite</strong> ein. Es liest nur; ein zusätzlicher HA-Helfer ist nicht erforderlich. Die auswählbaren Seiten werden unter <strong>Seite [0]</strong>, <strong>Seite [1]</strong> usw. zugeordnet. <strong>Werteanzahl bis</strong> ist der höchste Index: <code>1</code> ergibt zwei Einträge, <code>0</code> genau einen; Studio erlaubt maximal Index 50.</p><p><code>false</code>/<code>off</code> wählt Index 0, <code>true</code>/<code>on</code> Index 1. Ganzzahlige Zustände wählen den entsprechenden Index. Leere, nicht verfügbare, gebrochene oder außerhalb der Liste liegende Werte wählen keine Seite. Ohne Entität gilt bei neuen Widgets Index 0. Der Editor zeigt die gewählte Seite als Textvorschau; die Runtime bettet sie ein. Ein unverändertes Ziel wird bei Zustandsaktualisierungen nicht neu geladen. Fehlende Seiten und rekursive Einbettungen werden verhindert.</p><p>Neue Widgets starten mit <strong>300 × 200 Pixeln</strong> und ausschließlich aktiviertem <strong>CSS Allgemein</strong>. Die zentral abschaltbaren Umsteigerhinweise erläutern Index und Seitenabhängigkeit. Im Widget-JSON-Export sind die referenzierten Projektseiten nicht enthalten; für den geplanten vollständigen Projekt-Export müssen sämtliche benötigten Seiten mitgeliefert werden. Das Widget ist von <strong>Dashboard in widget</strong> zu unterscheiden, das ein HA-Dashboard öffnet.</p><h2 id="ha-grafik-–-interaktiv-11" tabindex="-1">HA Grafik – Interaktiv (11) <a class="header-anchor" href="#ha-grafik-–-interaktiv-11" aria-label="Permalink to &quot;HA Grafik – Interaktiv (11)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Aktuelle Funktion</th></tr></thead><tbody><tr><td>Universal Element</td><td>Standardzustand und bis zu 20 bedingte Zustände; Symbol, Bild, Text oder HTML. Schalten, Taster, Anzeige und Navigation mit Einzel- oder getrennten Tasten.</td></tr><tr><td>Calendar</td><td>Monatsansicht mit Datumsauswahl, Heute-Markierung, Tagessperren und Kalenderwochen.</td></tr><tr><td>Terminkalender</td><td>Termine in Monats-, Wochen-, Tages-, Jahres- und Listenansichten; mehrere Quellen und Farbregeln.</td></tr><tr><td>Checkbox</td><td>Eigene false-/true-Werte, Zustandstexte, vier Textpositionen und Boxgestaltung.</td></tr><tr><td>Schieberegler</td><td>Horizontaler/vertikaler Zahlenregler mit Wertetikett, Schrittmarkierungen und getrennten Stilen für Spur und Daumen.</td></tr><tr><td>Tabelle</td><td>JSON-Tabelle mit Spaltenformaten, Formeln, Sortierung, Filtern, Seitenaufteilung und Zeilenfarben.</td></tr><tr><td>Lauftext</td><td>Statischer Text oder HA-Zustand als fortlaufender Ticker mit Richtung, Geschwindigkeit und Hover-Pause.</td></tr><tr><td>Werteliste</td><td>Text in einzelne Listeneinträge aufteilen; acht Zeichenarten, Nummerierung, eigene Zeichen und Abstände.</td></tr><tr><td>Schalten</td><td>Eigene false-/true-Werte und Zustandstexte; getrennte Spur-/Daumenstile mit Stilübernahme.</td></tr><tr><td>Radialer Schieberegler</td><td>Zahlenregler mit Start-/Endwinkel, Wert und Bezeichnung sowie eigenen Spur-/Daumenstilen.</td></tr><tr><td>Dropdown</td><td>HA- oder eigene Optionen mit Titel, bedingtem Hintergrund und getrennten Menü-/Widget-Schatten.</td></tr></tbody></table><h3 id="dropdown" tabindex="-1">Dropdown <a class="header-anchor" href="#dropdown" aria-label="Permalink to &quot;Dropdown&quot;">​</a></h3><p>Ab <strong>0.1.182</strong> bietet <strong>Dropdown</strong> unter <strong>Interaktiv</strong> eine Optionsauswahl mit optionalem Titel, standardmäßig <strong>300 × 50 px</strong>. Bei HA-<code>select</code> und <code>input_select</code> kommen die Optionen aus dem Attribut <code>options</code>. <strong>Eigene Optionen verwenden</strong> erlaubt bis zu <strong>200 Wert-/Textpaare</strong>; doppelte Werte erscheinen einmal. Die beiden Anzeigehäkchen wählen Wert, Text oder die Kombination; gleiche Texte werden nicht doppelt angezeigt. Sind beide aus, bleibt der Wert zur eindeutigen Auswahl sichtbar.</p><ul><li><strong>Schreiben:</strong> <code>select</code>/<code>input_select</code> verwenden ausschließlich aktuell erlaubte Optionen. Eigene Zahlenwerte schreiben an <code>input_number</code>, Texte bis 255 Zeichen an <code>input_text</code>. Unpassende Optionen werden gesperrt. Sensoren, fehlende Zustände, Schreibschutz und der Editor bleiben ohne Schreibzugriff; ohne Entität funktioniert eine lokale Auswahl.</li><li><strong>Hintergrundfarb-Bedingungen:</strong> bis zu <strong>20 Regeln</strong>, mit sechs Vergleichsoperatoren. Die erste passende Regel gewinnt. Ohne zusätzliche Hintergrund-Entität gilt der ausgewählte Wert; sonst deren Zustand. Unbekannte oder nicht verfügbare Zustände lösen keine Farbregel aus.</li><li><strong>CSS Dropdown:</strong> Schriftgröße, Text-, Hintergrund-, Hervorhebungs- und Rahmenfarbe, Rahmenbreite/-radius sowie Titelgröße/-farbe und vier Titelabstände. Der Titel kann die aktive Bedingungsfarbe übernehmen. <strong>Dropdown-Schatten</strong> gestaltet Auswahl und offenes Menü; <strong>Widget-Schatten</strong> den gesamten Bereich inklusive Titel. Beide haben X/Y-Versatz, Unschärfe, Ausdehnung und Farbe.</li><li><strong>Vom Widget:</strong> übernimmt ausschließlich die Darstellung eines anderen Dropdowns, einschließlich Titelstil und Schatten. Titeltext, Optionsliste, Entität und Regeln bleiben lokal. Gemeinsame Kopien erhalten passende Stilreferenzen; Zyklen werden abgefangen.</li><li><strong>Bedienung:</strong> Klick oder Pfeiltaste öffnet das Menü. Pfeiltasten, Pos1/Ende, Enter/Leertaste und Escape bedienen die Liste; Tab verlässt sie. Lange Einträge umbrechen im Menü, große Listen scrollen. Schreibschutz zeigt den Wert ohne Auswahlpfeil.</li></ul><p>Alle Einstellungen, eigenen Optionen, Regeln und Referenzen bleiben in Projekt-, Widget- und Paketexporten erhalten. Die Optionsliste ist ein eigenes Studio-Menü, damit Farben und Schatten einheitlich wirken.</p><p><img src="'+E+'" alt="Dropdowns mit bedingtem Hintergrund, Schreibschutz, geöffnetem Menü und übernommenem Stil"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/en/widgets/dropdown-widget.md" target="_blank" rel="noreferrer">inventwo Dropdown für VIS2</a>. Die HA-Anbindung und Darstellung sind eigenständig umgesetzt.</p><h3 id="radialer-schieberegler" tabindex="-1">Radialer Schieberegler <a class="header-anchor" href="#radialer-schieberegler" aria-label="Permalink to &quot;Radialer Schieberegler&quot;">​</a></h3><p>Ab <strong>0.1.181</strong> steht unter <strong>Interaktiv</strong> der <strong>Radiale Schieberegler</strong> bereit. Neue Widgets starten mit <strong>200 × 200 px</strong>, Bereich <strong>0–100</strong>, Schritt <strong>1</strong>, Startwinkel <strong>225°</strong> und Endwinkel <strong>135°</strong>. <strong>0° liegt oben</strong>; der Bogen läuft im Uhrzeigersinn, standardmäßig über <strong>270°</strong>. Gleiche Winkel ergeben einen Vollkreis; <strong>270° bis 90°</strong> ergibt einen oberen Halbkreis.</p><ul><li><strong>Allgemein:</strong> HA-Entität, Minimum, Maximum, Schritt, Start-/Endwinkel, Wert anzeigen, Bezeichnung anzeigen, Bezeichnung und Schreibschutz. Ohne Entität dient der Vorschauwert als Ausgangswert.</li><li><strong>CSS Radialregler – Spur:</strong> Spurfarbe, aktive Farbe, Breite <strong>1–50 px</strong> sowie Schattenfarbe, X/Y-Versatz und Unschärfe.</li><li><strong>CSS Radialregler – Daumen:</strong> Farbe, Größe <strong>1–50 px</strong> und eigener Schatten.</li><li><strong>CSS Radialregler – Wert:</strong> Wertgröße <strong>8–100 px</strong>, Wertfarbe, Bezeichnungsgröße <strong>8–50 px</strong> und Bezeichnungsfarbe. Zahlen werden bei Platzmangel verkleinert; lange Bezeichnungen gekürzt. Der vollständige Text bleibt als zugänglicher Name des Reglers erhalten.</li><li><strong>Vom Widget:</strong> Spur und Daumen können unabhängig von einem anderen Radialregler übernommen werden. Wertanzeige, Bezeichnung und Wertebereich bleiben lokal. Zyklen werden abgefangen; gemeinsame Kopien erhalten passende neue Referenzen.</li><li><strong>Bedienung:</strong> Ziehen oder Pfeiltasten ändern um einen Schritt, Bild auf/ab um zehn Schritte, Pos1/Ende wählen Minimum/Maximum. Die Bogenlücke wählt den näheren Endwert. Ein abgebrochener Ziehvorgang stellt den Ausgangswert wieder her und schreibt nichts.</li><li><strong>HA:</strong> Nur verfügbare <code>input_number</code>-Helfer werden beschrieben, beim Loslassen beziehungsweise Tastendruck. Grenzen und Schritt müssen zum Helfer passen. Sensoren und Schreibschutz erlauben ausschließlich Anzeige; fehlende Werte erscheinen als Gedankenstrich. Ohne Entität bleiben Änderungen lokal. Im Editor wird nichts geschrieben.</li></ul><p>Alle Einstellungen und Stilreferenzen bleiben in Projekt-, Widget- und Paketexporten erhalten.</p><p><img src="'+x+'" alt="Radialregler mit Standardbogen, Dezimalwert, Halbkreis und schreibgeschütztem Vollkreis"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/en/widgets/radial-slider-widget.md" target="_blank" rel="noreferrer">inventwo Radial Slider für VIS2</a>. Studio verwendet eine eigene Umsetzung.</p><h3 id="schalten" tabindex="-1">Schalten <a class="header-anchor" href="#schalten" aria-label="Permalink to &quot;Schalten&quot;">​</a></h3><p>Ab <strong>0.1.180</strong> ergänzt <strong>Schalten</strong> unter <strong>Interaktiv</strong> den bisherigen Basis-<strong>Switch</strong>. Neue Widgets starten mit <strong>70 × 40 px</strong>, Textposition <strong>Ende</strong>, <strong>12 px</strong> Spur und <strong>16 px</strong> Daumen. Leere <strong>Wert false/true</strong> verwenden Boolean-Werte; eigene Zahlen oder Texte erlauben andere Wertepaare. <strong>Text falsch/wahr</strong> wird passend zum Zustand rechts, links, oben oder unten angezeigt und bleibt reiner Text.</p><ul><li><strong>CSS Schalten – Spur:</strong> getrennte Farben für false/true, Spurbreite <strong>1–50 px</strong>, Rundung <strong>1–100 %</strong> sowie X-/Y-Versatz, Unschärfe, Ausdehnung und getrennte Schattenfarben je Zustand.</li><li><strong>CSS Schalten – Daumen:</strong> getrennte Farben für false/true, Größe <strong>1–50 px</strong>, Rundung <strong>1–100 %</strong> und eigene Schatteneinstellungen. 100 % ergibt eine runde Form.</li><li><strong>Vom Widget:</strong> übernimmt Spur und Daumen unabhängig von einem anderen Schalten-Widget. Wertbindung und Texte bleiben lokal; zyklische Verweise enden sicher. Gemeinsames Kopieren ordnet die Verweise den kopierten Widgets zu.</li><li><strong>Bedienung:</strong> Klick auf Schalter oder Text, alternativ Leertaste. Die Runtime schreibt passende Werte an verfügbare <code>switch</code>-, <code>light</code>-, <code>input_boolean</code>-, <code>input_number</code>- oder <code>input_text</code>-Entitäten. Sensoren, unpassende Wertepaare, fehlende Zustände und der Editor bleiben nicht schreibfähig. Ohne Entität kannst du lokal umschalten.</li></ul><p>Schrift und Textfarbe kommen aus den üblichen CSS-Gruppen. Alle Werte, Zustandstexte, Stilfelder und Verweise bleiben im Projekt und Widget-/Paket-Export erhalten.</p><p><img src="'+T+'" alt="Schalten mit vier Textpositionen, unabhängiger Spurübernahme und gesperrter Sensoranzeige"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/en/widgets/switch-widget.md" target="_blank" rel="noreferrer">inventwo Switch für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="werteliste" tabindex="-1">Werteliste <a class="header-anchor" href="#werteliste" aria-label="Permalink to &quot;Werteliste&quot;">​</a></h3><p>Ab <strong>0.1.179</strong> ergänzt <strong>Werteliste</strong> unter <strong>Interaktiv</strong> die bisherigen Basis-Widgets <strong>ValueList Text/HTML/HTML Style</strong>. Neue Widgets starten mit <strong>200 × 150 px</strong>, Komma als Trennzeichen, aktivem Entfernen äußerer Leerzeichen und Ignorieren leerer Einträge. Mit HA-Entität gilt deren Zustand; ohne Entität verwendest du <strong>Text (manuell)</strong>. Die Liste liest ausschließlich und zeigt Text wörtlich an.</p><ul><li><strong>Trennzeichen:</strong> Zeichen oder mehrstellige Zeichenfolge; <code>\\\\n</code> für Zeilen und <code>\\\\t</code> für Tabulatoren. Ein leeres Trennzeichen zeigt den gesamten Text als einen Eintrag. Windows-Zeilenumbrüche werden berücksichtigt.</li><li><strong>Leerzeichen entfernen</strong> und <strong>Leere Einträge ignorieren</strong> arbeiten unabhängig. Bei ausgeschalteter Filterung bleiben leere Zeilen sichtbar; Nummern folgen den angezeigten Einträgen.</li><li><strong>Darstellung:</strong> Punkt, Kreis, Quadrat, Strich, Pfeil, Nummerierung, kein Zeichen oder eigenes Zeichen/Emoji. Zeichenfarbe ist unabhängig von der Textfarbe. Ohne Zeichen entfallen Zeichenfarbe und Zeichenabstand; das eigene Zeichenfeld erscheint nur bei dieser Auswahl.</li><li><strong>Abstände:</strong> Zeichen zu Text <strong>0–50 px</strong> (Standard <strong>8</strong>), Zeilen <strong>0–50 px</strong> (Standard <strong>4</strong>), Innenabstand <strong>0–200 px</strong> (Standard <strong>4</strong>). Lange Einträge brechen um; umfangreiche Listen lassen sich innerhalb des Widgets scrollen.</li></ul><p>Schrift, Textfarbe und Hintergrund stellst du über die normalen CSS-Gruppen ein. Alle Einstellungen bleiben im Projekt und im Widget-/Paket-Export erhalten.</p><p><img src="'+A+'" alt="Wertelisten mit Punkten, Nummerierung, eigenen Zeichen und umgebrochenem Text"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/en/widgets/value-list-widget.md" target="_blank" rel="noreferrer">inventwo Werteliste für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="lauftext" tabindex="-1">Lauftext <a class="header-anchor" href="#lauftext" aria-label="Permalink to &quot;Lauftext&quot;">​</a></h3><p>Ab <strong>0.1.178</strong> findest du <strong>Lauftext</strong> unter <strong>Interaktiv</strong>. Neue Widgets starten mit <strong>300 × 40 px</strong>, Richtung <strong>Links</strong>, <strong>80 px/s</strong>, <strong>3 Textkopien</strong> und <strong>50 px Abstand</strong>. Ohne Entität gilt <strong>Lauftext (statisch)</strong>; mit Entität hat der HA-Zustand Vorrang. Der Inhalt bleibt reiner Text und schreibt keine HA-Werte.</p><ul><li><strong>Richtung:</strong> Links oder Rechts; Geschwindigkeit <strong>10–500 px/s</strong>. Sie bleibt auch bei mehr Kopien konstant.</li><li><strong>Textkopien:</strong> <strong>1–200</strong>; kurze Texte werden zusätzlich so oft wiederholt, dass der Bereich gefüllt bleibt. <strong>Abstand zwischen Kopien</strong>: <strong>0–1000 px</strong>.</li><li><strong>Bei Hover pausieren:</strong> hält die Animation unter dem Mauszeiger an und setzt sie beim Verlassen fort. Unveränderte Texte laufen bei HA-Aktualisierungen ohne Neustart weiter.</li><li><strong>Darstellung:</strong> Hintergrund sowie Schrift, Textfarbe, Größe und Abstände über die normalen CSS-Einstellungen. Im Editor steht der Text still. <strong>Reduzierte Bewegung beachten</strong> ist standardmäßig aktiv: Bei der entsprechenden Systemeinstellung bleibt auch die Runtime statisch; die Option lässt sich pro Widget abschalten.</li></ul><p>Alle Einstellungen bleiben im Projekt und im Widget-/Paket-Export erhalten.</p><p><img src="'+B+'" alt="Lauftext mit Energie- und Wettermeldungen sowie automatisch ergänzten kurzen Textkopien"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/marquee-widget.md" target="_blank" rel="noreferrer">inventwo Lauftext für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="tabelle" tabindex="-1">Tabelle <a class="header-anchor" href="#tabelle" aria-label="Permalink to &quot;Tabelle&quot;">​</a></h3><p>Ab <strong>0.1.177</strong> ergänzt <strong>Tabelle</strong> unter <strong>Interaktiv</strong> die bisherige Basis-<strong>Table</strong>. Neue Widgets starten mit <strong>400 × 300 px</strong>, automatischen Spalten, sichtbarer Kopfzeile und ohne Seitenaufteilung. Daten sind eine JSON-Liste von Objekten, zum Beispiel:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;raum&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Küche&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;temperatur&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;leistung&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;aktiv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Die Runtime liest die gebundene HA-Entität oder das ausdrücklich ausgewählte <strong>HA-Attribut</strong>. Für längere Listen sollte ein Attribut verwendet werden. Ohne Entität und im Editor gelten die JSON-Testdaten. Die Tabelle liest ausschließlich; Sortieren, Filtern und Seitenwechsel schreiben keine HA-Werte.</p><ul><li><strong>Spalten:</strong> 0 erkennt die Schlüssel automatisch; bis zu 50 Spalten lassen sich konfigurieren. Möglich sind Ausblenden, Schlüssel, Titel, Breite, Ausrichtung, Präfix/Suffix und Platzhalter. Formate: Text, Zahl mit Dezimal-/Tausendertrennzeichen, Boolean als gesperrte Checkbox, Datum/Uhrzeit mit eigenem Muster, Bild, URL und IP-Adresse. Inhalte werden als Text behandelt; Bilder und Links benötigen eine erlaubte URL.</li><li><strong>Formeln:</strong> rechnen mit Zahlenfeldern der Zeile, beispielsweise <code>leistung * 2</code>. Unterstützt werden <code>+ - * / % **</code> und Klammern. Es wird kein JavaScript ausgeführt; ungültige Formeln verwenden den Platzhalter. Eigene Datumsmuster unterstützen <code>YYYY</code>, <code>YY</code>, <code>MM</code>, <code>M</code>, <code>DD</code>, <code>D</code>, <code>hh</code>, <code>h</code>, <code>mm</code>, <code>ss</code>, <code>sss</code>, <code>WD</code>, <code>WDL</code>, <code>KW</code> und <code>K</code>.</li><li><strong>Sortierung und Filter:</strong> Standardsortierung nach Schlüssel und Richtung; optional bis zu 20 Standardsortierungen mit Priorität. Klicks auf sortierbare Kopfzeilen wechseln aufsteigend/absteigend/ohne Sortierung. Automatische Spalten sind sortierbar; manuelle Spalten bieten eigene Sortier- und Filteroptionen. Filter wählen die zugelassenen Zellwerte. Die Zeilenbegrenzung gilt nach Filtern und Sortieren, vor der Seitenaufteilung. Kopfzeilen können beim Scrollen fixiert werden.</li><li><strong>Zeilenbedingungen:</strong> bis zu 20 Regeln nach Schlüssel oder Spaltenindex ab 0, mit sechs Vergleichsoperatoren. Die erste passende Regel bestimmt Hintergrund, Textfarbe der ganzen Zeile und/oder der Bedingungsspalte. <strong>Summenzeile markieren</strong> zieht eine Doppellinie über der letzten Ergebniszeile; Summen müssen bereits in den Daten stehen.</li><li><strong>CSS Tabelle:</strong> neutrale Gruppen <strong>Darstellung</strong>, <strong>Rahmenradius</strong>, <strong>Rahmen</strong> und <strong>Äußerer Schatten</strong>, mit HEX-Farben, Zeilen-/Kopfhöhen, Zeilenrändern, getrennten Ecken und Randseiten. <strong>Vom Widget</strong> übernimmt jede Gruppe unabhängig von einer anderen Tabelle; gemeinsam kopierte Widgets erhalten passende Verweise. <strong>CSS Allgemein</strong> bleibt aktiviert.</li></ul><p>Der Widget-JSON-Export enthält Spalten, Regeln, Stile und Quellenbindung. Benötigte HA-Entitäten, Attribute und referenzierte Stilwidgets müssen am Ziel vorhanden sein. Ohne Entitätsbindung bleiben die gespeicherten JSON-Daten nutzbar. Kleine Umsteigerhinweise lassen sich zentral abschalten.</p><p><img src="'+H+'" alt="Interaktive Tabelle mit Sortierung, Zeilenbedingungen, berechneter Leistung und Seitenaufteilung"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/table-widget.md" target="_blank" rel="noreferrer">inventwo Tabelle für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="schieberegler" tabindex="-1">Schieberegler <a class="header-anchor" href="#schieberegler" aria-label="Permalink to &quot;Schieberegler&quot;">​</a></h3><p>Ab <strong>0.1.176</strong> steht unter <strong>Interaktiv</strong> ein eigener <strong>Schieberegler</strong> bereit. Der bisherige <strong>Slider</strong> unter Basis bleibt erhalten. Neue Widgets starten mit <strong>150 × 40 px</strong>, Bereich <strong>0–100</strong>, Schritt <strong>1</strong>, horizontaler Ausrichtung und sichtbaren Min./Max.-Werten.</p><ul><li><strong>Allgemein:</strong> optionale Überschrift mit Abstand, Einheit, HA-Entität, Mindest-/Maximalwert, Schritt und Vorschauwert. Vertikale Regler steigen von unten nach oben. Das Wertetikett erscheint beim Bedienen, immer oder nie. Überschrift und Einheit werden als Text angezeigt.</li><li><strong>Schrittmarkierungen:</strong> automatisch im eingestellten Markierungsabstand oder an eigenen Positionen aus einer Kommaliste, zum Beispiel <code>-20,0,20,50,80</code>. Markierungen sind unabhängig vom Bedienschritt und können innerhalb der Spur oder oben/unten bzw. links/rechts stehen. Dichte Skalen werden auf höchstens 201 Markierungen ausgedünnt; Zahlenbeschriftungen passen sich der Widgetgröße an.</li><li><strong>CSS Schieberegler – Spur / Daumen:</strong> HEX-Farben, Spurbreite, Daumengröße, Rundung in Prozent und getrennte Schatten mit X/Y-Versatz, Unschärfe und Ausdehnung. Der Spurtyp bietet Normal, Umgekehrt oder Keine aktive Spur. Daumengröße <strong>0</strong> blendet den Daumen aus. <strong>Vom Widget</strong> übernimmt jede Gruppe unabhängig von einem anderen Schieberegler; gemeinsam kopierte Widgets erhalten passende interne Verweise. <strong>CSS Allgemein</strong> bleibt aktiviert.</li><li><strong>Bedienung:</strong> zum Schreiben ist ein verfügbarer <code>input_number</code>-Helfer nötig. Minimum, Maximum und Schritt müssen zum Helfer passen. Sensoren und nicht verfügbare Entitäten werden nur angezeigt. <strong>Schreibgeschützt</strong> verhindert Änderungen. Ohne Entität bleibt der Wert lokal; im Editor wird nichts geschrieben. HA-Schreibaufträge werden beim Abschluss einer Änderung gesendet.</li></ul><p>Beim Widget-JSON-Export werden sämtliche Regleroptionen, Stile und Entitätsbindungen gespeichert. Die Entität und referenzierte Stil-Quellwidgets müssen am Ziel ebenfalls vorhanden sein. Für Überschrift, Wertetikett und Skala kann ein größeres Widget sinnvoll sein.</p><p><img src="'+W+'" alt="Horizontaler und vertikaler Schieberegler, Fortschrittsanzeige und eigene Markierungen"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/slider-widget.md" target="_blank" rel="noreferrer">inventwo Schieberegler für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="checkbox" tabindex="-1">Checkbox <a class="header-anchor" href="#checkbox" aria-label="Permalink to &quot;Checkbox&quot;">​</a></h3><p>Ab <strong>0.1.175</strong> ergänzt <strong>Checkbox</strong> unter <strong>Interaktiv</strong> die bisherige <strong>Bool Checkbox</strong> aus Basis. Neue Widgets starten mit <strong>70 × 40 px</strong>, <strong>24 px</strong> Boxgröße und Textposition <strong>Ende</strong>.</p><ul><li><strong>Allgemein:</strong> HA-Entität, false-/true-Werte, Text falsch/wahr, Textposition und Testzustand. Leere Werte verwenden <code>false</code> und <code>true</code>. Die Positionen Ende/Start/Oben/Unten setzen den Text rechts/links/oberhalb/unterhalb der Box. Texte werden als Text angezeigt.</li><li><strong>CSS Checkbox – Stil:</strong> optionale HEX-Boxfarben für inaktiv/aktiv, Boxgröße von 0 bis 50 px und <strong>Vom Widget</strong> für die Stilübernahme einer anderen Checkbox. Zyklische Verweise enden sicher; gemeinsam kopierte Widgets erhalten passende interne Verweise. Schrift und Textfarbe folgen den allgemeinen CSS-Einstellungen. <strong>CSS Allgemein</strong> bleibt aktiviert.</li><li><strong>Bedienung:</strong> Ohne Entität wird lokal geschaltet. <code>switch</code>, <code>light</code> und <code>input_boolean</code> unterstützen boolesche Werte bzw. on/off und 0/1. Zahlenpaare benötigen <code>input_number</code>, Textpaare <code>input_text</code>. Sensoren, nicht verfügbare Entitäten und unpassende Wertepaare bleiben schreibgeschützt. Im Editor wird nichts geschrieben. Laufende HA-Schreibaufträge sperren die Checkbox vorübergehend.</li></ul><p>Beim JSON-Export werden Werte, Texte, Stil und Entitätsbindung gespeichert. Die Entitäten müssen am Ziel existieren; referenzierte Stil-Quellwidgets müssen ebenfalls enthalten sein. Die kleinen roten Hinweise folgen <strong>Umsteigerhinweise anzeigen</strong>.</p><p><img src="'+D+'" alt="Checkbox mit Zustandstext und Stilübernahme"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/checkbox-widget.md" target="_blank" rel="noreferrer">inventwo Checkbox für VIS2</a>. Studio verwendet eine eigene Implementierung.</p><h3 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h3><p><strong>Calendar</strong> ist eine Monatsansicht zur Datumsauswahl, keine Terminanzeige. Neue Widgets starten mit <strong>320 × 350 px</strong>, Tageszellen von <strong>36 px</strong>, Montag als Wochenbeginn und Hervorhebung des heutigen Tages. <strong>Allgemein</strong> enthält die HA-Entität, das Werteformat, ein Testdatum nur für den Editor, Schreibschutz, Vergangenheits-/Zukunftssperre, Monats-/Jahresnavigation, Wochenbeginn, Kalenderwochen und Zellgröße (20–80 px).</p><ul><li><strong>Zeitstempel (Zahl, ms):</strong> Millisekunden seit Epoch, zum Schreiben in einen <code>input_number</code>-Helfer. Wähle dessen Wertebereich ausreichend groß. Die Datumsauswahl schreibt Mitternacht in der lokalen Browser-Zeitzone.</li><li><strong>ISO-Datum:</strong> <code>JJJJ-MM-TT</code>, zum Schreiben in einen <code>input_text</code>-Helfer. Ein Sensor kann das Datum liefern, wird aber nicht beschrieben. Nur verfügbare Helfer im passenden Format erlauben die Datumsauswahl; Schreibschutz sperrt auch die Navigation.</li><li>Ohne Entität bleibt die Auswahl lokal in der Runtime und wird nicht in das Projekt geschrieben. <strong>Testdatum</strong> wird ausschließlich im Editor verwendet; die Runtime ignoriert es. Der Editor schreibt keine Datumswerte und sperrt die Kalenderbedienung.</li><li>Vergangene und zukünftige Tage werden relativ zum lokalen heutigen Datum gesperrt. Heute bleibt auswählbar. <strong>ISO-8601</strong> berücksichtigt Kalenderwochen am Jahreswechsel; <strong>Einfach</strong> setzt KW 1 auf die Woche mit dem 1. Januar und berücksichtigt den gewählten Wochenbeginn.</li></ul><p>Die sechs neutralen Gruppen <strong>CSS Kalender – Kopfzeile / Wochentage / Tag / Ausgewählter Tag / Heute / Kalenderwoche</strong> bieten HEX-Farben, Tagesradius und den Schatten des ausgewählten Tages. Nicht gesetzte Textfarben verwenden die Studio-Themenfarben. <strong>Vom Widget</strong> übernimmt ausschließlich den jeweiligen Bereich eines anderen Calendar-Widgets; zyklische oder ungültige Verweise enden ohne Endlosschleife. Bei gemeinsamem Kopieren werden interne Verweise angepasst; beim Export müssen referenzierte Kalender mit enthalten sein. <strong>CSS Allgemein</strong> bleibt aktiviert und speichert Position und Größe. Die kleinen roten Helferhinweise folgen <strong>Umsteigerhinweise anzeigen</strong>.</p><p>Monat und Jahr können direkt gewählt werden. Ist Monats-/Jahresnavigation deaktiviert, bleiben in der Runtime die Pfeile für den vorherigen und nächsten Monat verfügbar. Ein fehlgeschlagener HA-Schreibauftrag zeigt einen Fehler und erlaubt einen erneuten Versuch.</p><p><img src="'+L+'" alt="Calendar mit Datumsauswahl, Heute-Markierung und Kalenderwochen"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/calendar-widget.md" target="_blank" rel="noreferrer">Kalender von inventwo für VIS2</a>. Studio verwendet eine eigene Implementierung ohne Abhängigkeit vom ioBroker-Paket.</p><h3 id="terminkalender" tabindex="-1">Terminkalender <a class="header-anchor" href="#terminkalender" aria-label="Permalink to &quot;Terminkalender&quot;">​</a></h3><p>Ab <strong>0.1.174</strong> zeigt der <strong>Terminkalender</strong> Termine ausschließlich lesend an. Die Standardgröße ist <strong>600 × 500 px</strong>. Zur Auswahl stehen Monat, Woche mit Stundenraster, Tag, Jahr mit zwölf Monaten und Listen für Tag, Woche, Monat oder Jahr. Kopfzeile und Navigation lassen sich getrennt abschalten. Wochenbeginn, ISO-/einfache Kalenderwochen und die Uhrzeit-Linie sind einstellbar. <strong>Max. Termine pro Tag</strong> begrenzt die sichtbaren Einträge; <code>0</code> zeigt alle. Weitere Termine öffnen sich über <strong>+N weitere</strong>.</p><ul><li><strong>Termine (HA-Entität):</strong> <code>calendar.*</code> lädt den sichtbaren Zeitraum über <a href="https://www.home-assistant.io/integrations/calendar/" target="_blank" rel="noreferrer">calendar.get_events</a>. Der normale Kalenderzustand enthält keine vollständige Terminliste. Andere HA-Entitäten können eine JSON-Liste als Zustand liefern.</li><li><strong>Termine (JSON, ohne Entität):</strong> Eine direkt gespeicherte JSON-Liste dient als lokale Quelle. Unterstützt werden <code>title</code> / <code>summary</code> / <code>event</code>, <code>start</code> / <code>_date</code>, optional <code>end</code> / <code>_end</code>, <code>allDay</code> / <code>_allDay</code> und <code>color</code> / <code>_calColor</code>. Beginn und Ende sind ISO-Datum, ISO-Datum mit Uhrzeit oder Millisekunden. Ein reines Datum gilt als ganztägig; dessen Ende ist exklusiv. Fehlendes oder mit dem Beginn identisches Ende nutzt die Standarddauer.</li><li><strong>Weitere Kalender:</strong> Bis zu 20 Quellen mit HA-Entität, optionaler HEX-Quellfarbe und Legendentext. Sobald die Anzahl größer als <code>0</code> ist, ersetzen diese Quellen das einzelne Entitätsfeld und die lokale JSON-Liste. Leere Quellen liefern keine Termine. Die Legende lässt sich abschalten.</li><li><strong>Termin-Farbregeln:</strong> Bis zu 20 Regeln vergleichen einen Titelteil ohne Beachtung der Groß-/Kleinschreibung. Die erste passende Regel setzt die Hintergrundfarbe. Die Quellfarbe bleibt als linker Streifen bzw. Punkt in Listen sichtbar.</li></ul><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Familienausflug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;end&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-05&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#3686BD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Die sechs neutralen Gruppen <strong>CSS Terminkalender – Kopfzeile / Wochentage / Tag / Heute / Termin-Kacheln / Rahmen</strong> bieten HEX-Farben, Schriftgrößen, Radien, Rahmen und Hover-Farben für Navigationsbuttons. <strong>Vom Widget</strong> übernimmt den jeweiligen Bereich eines anderen Terminkalenders; zyklische Verweise enden sicher. <strong>CSS Allgemein</strong> bleibt aktiviert. Umsteigerhinweise folgen dem zentralen Schalter. Editor-Vorschauen schreiben keine Termine und lassen sich weiterhin ziehen und skalieren.</p><p>HA-Kalender werden beim Zeitraumwechsel und frühestens nach 60 Sekunden erneut gelesen; JSON-Entitätszustände folgen der normalen Abfrage alle fünf Sekunden. Fehler werden im Widget angezeigt. <code>.ics</code>-Dateien werden über eine HA-Kalenderintegration eingebunden. Es gibt keine Termin-Erstellung, -Bearbeitung oder -Löschung.</p><p>Beim Widget-Export werden Konfiguration und direkt eingetragenes JSON mitgenommen, aber keine live abgerufenen HA-Termine. Am Ziel müssen die verwendeten Entitäten verfügbar sein; referenzierte CSS-Quellwidgets müssen ebenfalls mitgeliefert werden.</p><p><img src="'+F+'" alt="Terminkalender mit Farbregeln und zusätzlichem Termin-Popup"></p><p>Funktionsreferenz: <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/de/widgets/event-calendar-widget.md" target="_blank" rel="noreferrer">inventwo-Terminkalender für VIS2</a>. Studio verwendet eine eigene Datenanbindung und den lokal mitgelieferten <a href="https://legacy.fullcalendar.io/v6/" target="_blank" rel="noreferrer">FullCalendar 6.1.21</a> unter MIT-Lizenz; das ioBroker-Paket ist nicht erforderlich.</p><h3 id="universal-element" tabindex="-1">Universal Element <a class="header-anchor" href="#universal-element" aria-label="Permalink to &quot;Universal Element&quot;">​</a></h3><p><img src="'+R+'" alt="Beschriftungen bleiben nach dem Klick in allen drei betroffenen Widgets sichtbar"></p><p>Ab Studio <strong>0.1.195</strong> übernimmt ein leerer Zustandstext den Text des Standardzustands, danach den optionalen Titel. So bleibt etwa „Licht Garage“ beim Schalten sichtbar, auch bei getrennten Tasten. Nichtleere Zustandstexte ersetzen weiterhin den Standardtext. Bei <strong>Checkbox</strong> und <strong>Schalten</strong> übernimmt ein leerer Zustandstext den anderen Zustandstext, danach den Titel. Für eine Anzeige ohne Beschriftung bleiben alle Textfelder und der Titel leer. Der Editorname wird nicht eingeblendet.</p><p>Der frühere Name <strong>State Element</strong> bleibt als Suchbegriff erhalten. Bestehende Projekte verwenden weiterhin denselben Widget-Typ <code>universal-button</code>.</p><ul><li><strong>Allgemein:</strong> HA-Entität, Bedienung, Modus, false-/true-Werte und Navigations-URL. Ohne Entität arbeitet das Element lokal. Ein Sensor ist kein Schreibziel; Zahlen und Text benötigen passende <code>input_number</code>-/<code>input_text</code>-Helfer. Nur Anzeige und Navigation schreiben keinen HA-Zustand.</li><li><strong>Klick-Feedback:</strong> Dauer in Millisekunden und sechs optionale Farben; <code>0</code> deaktiviert die Rückmeldung. Sie bleibt während des Zustandswechsels sichtbar. „Klick durchlassen“ reicht Mausklicks in der Runtime an darunterliegende Elemente weiter und deaktiviert die eigene Bedienung.</li><li><strong>Standardzustand / Zustände und Inhalte:</strong> Der erste passende aktive Zustand gewinnt; ohne Treffer erscheint der Standardzustand. Regeln vergleichen die Widget-Entität oder eine andere HA-Entität mit <code>==</code>, <code>!=</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code> oder <code>&lt;=</code>. Zustände lassen sich kopieren, löschen, verschieben und deaktivieren. Eine kleinere Anzahl behält die ausgeblendeten Einträge. „Klick deaktivieren wenn aktiv“ sperrt nur den aktuell passenden Zustand. Text kann zusätzlich zum Symbol oder Bild angezeigt werden; das Blinkintervall <code>0</code> bedeutet kein Blinken.</li><li><strong>Text / Inhalt / Ausrichtung:</strong> Textdekoration, getrennte Außenabstände, Größe, Drehung und Spiegelung des Inhalts; Zeile oder Spalte, Verteilung, Text- und Inhaltsausrichtung sowie umgekehrte Reihenfolge. Eine ausdrücklich gewählte Inhaltsart im Bereich „Inhalt“ gilt für alle Zustände. Zustandsgröße <code>0</code> verwendet die Widget-Größe des Inhalts.</li><li><strong>Transparenz / Abstand:</strong> Hintergrund und Inhalt haben eigene Opazitäten; vier Innenabstände sind unabhängig einstellbar.</li><li><strong>Ecken / Rahmen / Äußerer Schatten / Innerer Schatten / Form:</strong> Vier abgerundete oder abgeschrägte Ecken, getrennte Rahmenbreiten und Rahmenstil sowie Schatten mit Versatz, Unschärfe, Größe und Farbe. Formen reichen vom Rechteck bis zum Stern und eigenen Polygonen. Polygonpunkte werden als Prozentpaare eingegeben; ungültige Eingaben fallen auf das Rechteck zurück. Formdrehung und Formradius betreffen Polygone; die normalen Ecken gelten für Rechtecke.</li></ul><p><strong>Vom Widget</strong> übernimmt die Einstellungen des jeweiligen Bereichs dauerhaft von einem anderen Universal Element. Änderungen am Quellwidget wirken sofort; fehlende Quellen und zyklische Verweise führen zu lokalen Einstellungen statt einer Endlosschleife. Farbverweise übernehmen die Standardfarben des Quellwidgets. Der Haken „eigene Farbe“ schaltet einen HEX-Farbwert ein; ohne Haken bleibt die Farbe vererbt. Beim gemeinsamen Kopieren werden interne Verweise angepasst; beim Export müssen die referenzierten Widgets mit enthalten sein. <strong>CSS Allgemein</strong> bleibt aktiv, damit Position und Größe gespeichert werden. Die kleinen roten Umsteigerhinweise lassen sich zentral ausblenden.</p><p><img src="'+Z+'" alt="Universal Element mit neutralen Einstellungsbereichen und mehreren Darstellungsformen"></p><p>Die Funktionen orientieren sich an der <a href="https://github.com/inventwo/ioBroker.vis-2-widgets-inventwo/blob/main/docs/en/widgets/universal/styling-and-shapes.md" target="_blank" rel="noreferrer">VIS2-Universal-Dokumentation von inventwo</a>. Studio verwendet eine eigene Implementierung und benötigt das ioBroker-Paket nicht.</p><h2 id="ha-grafik-–-gauges-10" tabindex="-1">HA Grafik – Gauges (10) <a class="header-anchor" href="#ha-grafik-–-gauges-10" aria-label="Permalink to &quot;HA Grafik – Gauges (10)&quot;">​</a></h2><p>Ab <strong>0.1.186</strong> gibt es ein eigenes, goldbraun hinterlegtes Instrumenten-Set. Als Funktionsreferenz dient der <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-gauges/tree/main/src-widgets/src" target="_blank" rel="noreferrer">aktuelle Quellcode von ioBroker.vis-2-widgets-gauges</a>, der zehn Typen enthält. Die README des Referenzprojekts zeigt nur die ersten drei. Studio zeichnet die Instrumente selbst als SVG; ioBroker ist nicht erforderlich. Es handelt sich um eigenständige Studio-Widgets, nicht um einen direkten Import der ioBroker-Konfiguration.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Funktion und besondere Einstellungen</th></tr></thead><tbody><tr><td>Farbmesser</td><td>Farbige Bogenabschnitte, Zeiger, Bogenwinkel und Min./Max.-Beschriftungen.</td></tr><tr><td>Wasserstand</td><td>Kreisförmige Füllstandsanzeige mit einstellbarer Wellenhöhe und optionaler Animation.</td></tr><tr><td>Batterie</td><td>Horizontale oder vertikale Batterie, bis zu 20 Zellen, Ladezustand-Entität und Ladesymbol.</td></tr><tr><td>Bogenmesser</td><td>Fortschrittsbogen, Drehung, bis zu 100 Segmente, Füllung ab Null und Zielwert-Entität.</td></tr><tr><td>Kompass</td><td>Grad und Himmelsrichtung, Nordversatz, Richtungsumkehr, mitdrehende Skala und Geschwindigkeits-Entität.</td></tr><tr><td>Linearmesser</td><td>Horizontaler oder vertikaler Balken beziehungsweise Zeiger mit Haupt-/Unterteilungen und Zielmarkierung.</td></tr><tr><td>Rundinstrument</td><td>Zeigerinstrument mit Farbband, beschrifteter Skala, Bogenwinkel, Drehung und Instrumentenrahmen.</td></tr><tr><td>Ringe</td><td>Bis zu acht getrennte Entitäten mit eigenen Bereichen, Farben, Bezeichnungen und Einheiten; Legende unten, seitlich oder ausgeblendet.</td></tr><tr><td>Tank</td><td>Zylinder, Rechteck oder liegender Tank mit Skala, Füllstand, optionalem Prozentwert und Wellen.</td></tr><tr><td>Thermometer</td><td>Säule und Kugel mit eigenem Wertebereich; Skala links, rechts oder beidseitig.</td></tr></tbody></table><p>Alle Instrumente lesen HA-Zustände und schreiben keine Werte. Ohne Entität gilt der Vorschauwert; eine fehlende oder nicht verfügbare gebundene Entität wird als <strong>—</strong> angezeigt. Werte außerhalb des Bereichs bleiben als Zahl sichtbar, während die Füllung auf 0–100 % begrenzt wird. Ein ungültiger Wertebereich zeigt ebenfalls <strong>—</strong>. Zahlen, Einheiten, Nachkommastellen, Bezeichnung, aktive Farbe, Skalen-/Spur-/Zeiger-/Textfarben und Größen sind konfigurierbar. Bis zu zehn Farbstufen werden nach ihren Obergrenzen sortiert; die erste passende Stufe gilt einschließlich ihres Grenzwerts. Alle Einstellungen und Entitätsbindungen werden im Projekt- und Widget-JSON gespeichert.</p><p>Bei Ringen wird die Hauptentität durch die einzelnen Ring-Entitäten ersetzt. Ladezustand, Geschwindigkeit und Zielmarkierungen werden zusammen mit den Hauptwerten abgefragt. Wellen laufen nur in der Runtime und respektieren die Einstellung für reduzierte Bewegung. Die Null- und Vollanzeige bleibt ohne Wellen exakt.</p><p><img src="'+V+'" alt="Alle zehn Gauges als eigenständige Studio-Instrumente"></p><h2 id="ha-grafik-–-datenfluss-3" tabindex="-1">HA Grafik – Datenfluss (3) <a class="header-anchor" href="#ha-grafik-–-datenfluss-3" aria-label="Permalink to &quot;HA Grafik – Datenfluss (3)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Aktuelle Funktion</th></tr></thead><tbody><tr><td><a href="./datenfluss">Wert-Verbindung</a></td><td>Gerichtete interne Wertübertragung; einfache Linie im Editor, unsichtbar in der Runtime.</td></tr><tr><td><a href="./datenfluss">Wert-Konverter</a></td><td>Konvertiert Zahlen, Text, Schaltzustände und Einheiten mit eigenem Dialog und Typvorschau; unsichtbar in der Runtime.</td></tr><tr><td><a href="./datenfluss">Wert-Berechnung</a></td><td>Gleiche vier Rechnungen wie SVG LineBox Math; standardmäßig unsichtbar in der Runtime.</td></tr></tbody></table><h2 id="ha-grafik-–-spezial-4" tabindex="-1">HA Grafik – Spezial (4) <a class="header-anchor" href="#ha-grafik-–-spezial-4" aria-label="Permalink to &quot;HA Grafik – Spezial (4)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Aktuelle Funktion</th></tr></thead><tbody><tr><td>Dashboard in widget</td><td>Bettet ein HA-Dashboard in der Runtime ein. Größe 32–800 × 32–640 Pixel, Standard 300 × 200. Der Editor zeigt eine auswählbare Vorschau.</td></tr><tr><td><a href="./svg-line">SVG-Line</a></td><td>Zeichnet und animiert Verbindungen zwischen Widgets, mit Andockpunkten, manuellem Mehrpunktpfad und gezielter Kopplung über Sammelpunkte.</td></tr><tr><td><a href="./svg-linebox-math">SVG LineBox Math</a></td><td>Sichtbares Quadrat mit 16 Anschlüssen A–P. Eigene Formel oder Durchschnitt belegter Eingänge; Mehrfachbelegung wird je Anschluss summiert. Interne Wertweitergabe ohne zusätzliche HA-Entität.</td></tr><tr><td><a href="./svg-linebox">SVG LineBox</a></td><td>Im Editor sichtbarer Verteiler: Zahlenwerte eingehender Linien summieren und an Ausgangslinien sowie optional an einen HA-Zahlenhelfer weitergeben. Ein einstellbarer Kreis verdeckt in der Runtime die verbundenen Linienenden.</td></tr></tbody></table><h3 id="dashboard-in-widget" tabindex="-1">Dashboard in widget <a class="header-anchor" href="#dashboard-in-widget" aria-label="Permalink to &quot;Dashboard in widget&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Export in eine externe Runtime</p><p>Für Visualisierungen innerhalb von Home Assistant vorgesehen. Wenn ein Export in die externe Runtime geplant ist, dieses Widget möglichst nicht verwenden. Das eingebundene Dashboard wird nicht mit exportiert und benötigt weiterhin Home Assistant sowie eine Browser-Anmeldung.</p><p>Seit <strong>0.1.159</strong> steht dieser Hinweis dauerhaft in den Widget-Einstellungen, unabhängig von „Umsteigerhinweise anzeigen“. Beim JSON-Export ausgewählter Widgets erscheint er ebenfalls, wenn ein Dashboard enthalten ist; eigene Tab-Flächen werden mitgeprüft. Der Dialog nennt die betroffenen Widgets und bietet <strong>Trotzdem exportieren</strong> oder <strong>Abbrechen</strong>. Exportiert wird nur die Dashboard-Bindung. Der vollständige Projekt-Export für die externe Runtime ist weiterhin geplant.</p></div><p><img src="'+I+'" alt="HA-Dashboard-Vorschau im Editor für lovelace Ansicht 0"></p><p><em>Editor-Vorschau für /lovelace/0. Das lokale Testbild zeigt kein angemeldetes HA-Dashboard.</em></p><p><strong>Dashboard</strong> öffnet über „…“ die Liste der HA-Dashboards. Alternativ lässt sich ein Pfad wie <code>/lovelace</code> oder <code>/dashboard-solar</code> direkt eingeben. <strong>Dashboard-Ansicht</strong> wählt optional einen Ansichtspfad oder eine Zahl, etwa <code>energie</code> oder <code>0</code>. Im HA-Ingress bleibt <strong>HA-Basis-URL</strong> leer. Bei direktem Studio-Zugriff wird dort die HA-Adresse eingetragen, beispielsweise <code>https://ha.example.org</code>.</p><p>Die Anmeldung nutzt die normale HA-Browsersitzung. Das Widget speichert keinen Token; die Dashboard-Auswahl gibt nur Titel und Pfade zurück. Andere Ursprünge können durch Browser- oder Einbettungsregeln blockiert werden. Eine erneute Anmeldung kann erforderlich sein. Normale Studio-Zustandsaktualisierungen laden ein bereits eingebettetes Dashboard nicht neu. Neue Widgets aktivieren nur CSS Allgemein; Umsteigerhinweise sind zentral abschaltbar. „View in widget“ bleibt für Studio-Seiten zuständig.</p>',258)])])}const X=M(q,[["render",N]]);export{Q as __pageData,X as default};
